fn fresh_state(card_id: CardId, base_damage: i32, base_block: i32) -> (CombatState, CreatureUid) {
    let mut state = CombatState {
        rng: sts2_core::dotnet_rng::Rng::new(0_i32),
        ..Default::default()
    };
    // Alive player -- a dead one trips the C# IsOverOrEnding select guard
    // in request_card_choice.
    state.player.current_hp = 80;
    state.player.max_hp = 80;
    let enemy_id = NonZeroU32::new(1).expect("nz");
    state.creatures.push(Creature {
        id: enemy_id,
        current_hp: 100,
        max_hp: 100,
        block: 0,
        powers: SmallVec::new(),
        species: Some(MonsterKind::Nibbit),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Nibbit"),
        ai: None,
    });
    let euid = CreatureUid(enemy_id);
    state.enemy_uids.push(euid);
    let card_uid = NonZeroU32::new(1).expect("nz");
    state.cards.push(Card {
        uid: sts2_core::CardUid(card_uid),
        card_id,
        cost: sts2_core::CardEnergyCost::new(1),
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        upgraded: false,
        base_damage,
        base_block,
        ..Card::pod_defaults()
    });
    state.player.play.push(sts2_core::CardUid(card_uid));
    (state, euid)
}

/// Push a fresh card into the draw pile (test scaffolding for the
/// draw/select cards below). Returns its uid.
fn push_draw_card_id(state: &mut CombatState, card_id: CardId) -> CardUid {
    let raw = u32::try_from(state.cards.len() + 1).expect("fits");
    let uid = sts2_core::CardUid(NonZeroU32::new(raw).expect("nz"));
    state.cards.push(Card {
        uid,
        card_id,
        cost: sts2_core::CardEnergyCost::new(1),
        card_type: CardType::Skill,
        target_type: TargetType::Self_,
        upgraded: false,
        base_damage: 0,
        base_block: 0,
        ..Card::pod_defaults()
    });
    state.player.draw.push(uid);
    uid
}

fn add_player_creature(state: &mut CombatState) {
    let player_id = NonZeroU32::new(99).expect("nz");
    state.creatures.push(Creature {
        id: player_id,
        current_hp: 80,
        max_hp: 80,
        block: 0,
        powers: SmallVec::new(),
        species: None,
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Player"),
        ai: None,
    });
    state.player.creature_uid = Some(CreatureUid(player_id));
}

/// SeekerStrike (sts2-rs-at4vs): deals damage AND opens a single-pick
/// AddFromDrawByType choice over (up to) 3 shuffled draw-pile cards.
#[test]
fn seeker_strike_damages_and_opens_draw_select() {
    install_pool();
    let (mut state, euid) = fresh_state(CardId::SeekerStrike, 9, 0);
    add_player_creature(&mut state);
    // combat_is_ending reads the raw PlayerCombatState.current_hp field (not
    // the creature accessor), which defaults to 0 — give the player HP so the
    // new lethal-suppression guard doesn't treat this fixture as combat-over.
    state.player.current_hp = 80;
    for _ in 0..5 {
        push_draw_card_id(&mut state, CardId::Finesse);
    }
    let hp0 = state.creatures[0].current_hp;
    let _ = lookup(CardId::SeekerStrike).expect("registered")(&mut state, Some(euid));
    assert_eq!(hp0 - state.creatures[0].current_hp, 9, "deals 9 damage");
    let pc = state.pending_choice.as_ref().expect("opens a choice");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::AddFromDrawByType);
    assert_eq!(pc.options.len(), 3, "presents 3 of the 5 draw cards");
}

/// A 1-card draw pile is `<= MinSelect`: C# `FromCombatPile` takes the card
/// with no prompt (CardSelectCmd.cs:397-400). Defect QX182.
#[test]
fn seeker_strike_single_draw_card_goes_to_hand_without_a_choice() {
    install_pool();
    let (mut state, euid) = fresh_state(CardId::SeekerStrike, 9, 0);
    add_player_creature(&mut state);
    state.player.current_hp = 80;
    push_draw_card_id(&mut state, CardId::Finesse);
    let only = state.player.draw[0];
    let _ = lookup(CardId::SeekerStrike).expect("registered")(&mut state, Some(euid));
    assert!(state.pending_choice.is_none(), "no prompt for a lone card");
    assert!(state.player.draw.is_empty());
    assert_eq!(state.player.hand.last().copied(), Some(only));
}

