/// SeekerStrike replicates C# `StableShuffle` (`ListExtensions.cs:10-19`):
/// `list.Sort()` by `CardModel.CompareTo` (`CardModel.cs:1745-1766` =
/// ordinal `Entry` string, then `CurrentUpgradeLevel`/upgraded ascending)
/// THEN Fisher-Yates — NOT a sort by the card's instance uid.
///
/// Bead `sts2-rs-i0f30`: the first fix sorted by `CardUid` (the shared
/// `Rng::stable_shuffle` `Ord` key), which regressed seeds 215/526. This
/// test pins the C#-correct `(Entry, upgraded)` key with a case where uid
/// order and `(Entry, upgraded)` order DISAGREE: a base + upgraded copy of
/// the SAME id where the **upgraded** copy has the **lower** uid. The
/// `(Entry, upgraded)` sort must place the base copy first (uid order would
/// place the upgraded copy first).
#[test]
fn seeker_strike_stable_shuffle_key_is_entry_upgraded_not_uid() {
    install_pool();

    // Helper: push a draw card with explicit id + upgrade flag, returns uid.
    fn push_draw_upg(state: &mut CombatState, card_id: CardId, upgraded: bool) -> CardUid {
        let raw = u32::try_from(state.cards.len() + 1).expect("fits");
        let uid = sts2_core::CardUid(NonZeroU32::new(raw).expect("nz"));
        state.cards.push(Card {
            uid,
            card_id,
            cost: sts2_core::CardEnergyCost::new(1),
            card_type: CardType::Skill,
            target_type: TargetType::Self_,
            upgraded,
            base_damage: 0,
            base_block: 0,
            ..Card::pod_defaults()
        });
        state.player.draw.push(uid);
        uid
    }

    // Build state with exactly 3 draw cards so the subset = full sorted pile
    // (count 3 = CardsVar(3)), making the options a deterministic function of
    // the sort key alone (Fisher-Yates of 3 elements is still a permutation of
    // the same set, but options[0..3] is the whole set — so we compare SETS
    // and the relative base-before-upgraded ordering of the sort, both of
    // which uid-sort would get wrong only via a different *starting* pile).
    //
    // To make the divergence observable in the OPTION SET, we instead use a
    // pile of 4 where the top-3-after-shuffle differs between the two keys.
    // uids: 2=BELIEVE_IN_YOU (upgraded), 3=BELIEVE_IN_YOU (base),
    //       4=ANGER (base), 5=UPPERCUT (base).
    // (Entry, upgraded) sort → [ANGER/4, BELIEVE_IN_YOU-base/3,
    //                            BELIEVE_IN_YOU-upg/2, UPPERCUT/5]
    // uid sort               → [BELIEVE_IN_YOU-upg/2, BELIEVE_IN_YOU-base/3,
    //                            ANGER/4, UPPERCUT/5]
    // These two starting permutations differ, so under a fixed RNG the
    // resulting top-3 option SET differs.
    fn make_state() -> (CombatState, CreatureUid) {
        let (mut state, euid) = fresh_state(CardId::SeekerStrike, 9, 0);
        add_player_creature(&mut state);
        // Raw player HP for combat_is_ending (see sibling test) so the
        // lethal-suppression guard doesn't short-circuit the draw select.
        state.player.current_hp = 80;
        push_draw_upg(&mut state, CardId::BelieveInYou, true); // uid 2 (upgraded, LOW uid)
        push_draw_upg(&mut state, CardId::BelieveInYou, false); // uid 3 (base, HIGH uid)
        push_draw_upg(&mut state, CardId::Anger, false); // uid 4
        push_draw_upg(&mut state, CardId::Uppercut, false); // uid 5
        (state, euid)
    }

    let (mut state, euid) = make_state();
    let _ = lookup(CardId::SeekerStrike).expect("registered")(&mut state, Some(euid));
    let pc = state.pending_choice.as_ref().expect("opens a choice");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::AddFromDrawByType);
    assert_eq!(pc.options.len(), 3, "presents 3 of the 4 draw cards");

    // Compute the C#-correct expected subset: sort the FULL pile by
    // (Entry, upgraded), run the SAME plain shuffle on a fresh state's
    // combat_card_selection stream, take the first 3.
    let (state_ref, _) = make_state();
    let mut sorted: Vec<CardUid> = state_ref.player.draw.to_vec();
    sorted.sort_by(|&a, &b| {
        let ca = &state_ref.cards[a.0.get() as usize - 1];
        let cb = &state_ref.cards[b.0.get() as usize - 1];
        sts2_core::cards::card_model_entry(ca.card_id)
            .cmp(sts2_core::cards::card_model_entry(cb.card_id))
            .then_with(|| ca.upgraded.cmp(&cb.upgraded))
    });
    let mut rng = state_ref.run_rng.combat_card_selection.clone();
    rng.shuffle(&mut sorted);
    let mut expected: Vec<CardUid> = sorted.into_iter().take(3).collect();
    // C# `FromCombatPile` presents the surfaced options ordered by
    // `(Rarity, Id)` (CardSelectCmd.cs:404-409), so the option order is that
    // presentation sort applied to the StableShuffle-selected subset.
    let entry_sort = |cards: &[Card], v: &mut Vec<CardUid>| {
        v.sort_by(|&a, &b| {
            let ca = &cards[a.0.get() as usize - 1];
            let cb = &cards[b.0.get() as usize - 1];
            crate::cards::spec_index::card_rarity_rank_csharp(ca.card_id)
                .cmp(&crate::cards::spec_index::card_rarity_rank_csharp(
                    cb.card_id,
                ))
                .then_with(|| {
                    sts2_core::cards::card_model_entry(ca.card_id)
                        .cmp(sts2_core::cards::card_model_entry(cb.card_id))
                })
        });
    };
    entry_sort(&state_ref.cards, &mut expected);

    let actual: Vec<CardUid> = pc.options.iter().filter_map(|o| o.card_uid).collect();
    assert_eq!(
        actual, expected,
        "options must match a (Entry, upgraded)-keyed StableShuffle, NOT a uid sort \
         (sts2-rs-i0f30 regression guard for seeds 215/526)"
    );

    // Belt-and-suspenders: prove the uid-sort key would produce a DIFFERENT
    // result, so this test actually discriminates the two keys.
    let (state_ref2, _) = make_state();
    let mut uid_sorted: Vec<CardUid> = state_ref2.player.draw.to_vec();
    uid_sorted.sort(); // CardUid Ord = instance-uid order
    let mut rng2 = state_ref2.run_rng.combat_card_selection.clone();
    rng2.shuffle(&mut uid_sorted);
    let mut uid_keyed: Vec<CardUid> = uid_sorted.into_iter().take(3).collect();
    entry_sort(&state_ref2.cards, &mut uid_keyed);
    assert_ne!(
        actual, uid_keyed,
        "test must discriminate: uid-sort and (Entry,upgraded)-sort should differ here"
    );
}

/// Bead `sts2-rs-isooo` (q6bix ENTROPY): `transform_card_to_random_for_hook`
/// transforms a hand card in place to a random card from the player's
/// combat-generatable pool, consuming exactly one `CombatCardSelection`
/// draw (C# `CardCmd.TransformToRandom` → `rng.NextItem(pool)`). The
/// pool excludes the original id, so a non-pool basic (StrikeIronclad)
/// always becomes a different card, and the result is deterministic
/// under a fixed seed.
#[test]
fn entropy_transform_to_random_picks_from_pool_and_advances_rng_once() {
    use super::helpers::transform_card_to_random_for_hook;

    let make = || {
        let (mut state, _euid) = fresh_state(CardId::StrikeIronclad, 6, 0);
        state.player.character = Some(sts2_core::potions::CharacterId::Ironclad);
        // Move the seeded card from play → hand (fresh_state stages it in play).
        let uid = sts2_core::CardUid(NonZeroU32::new(1).expect("nz"));
        state.player.play.clear();
        state.player.hand.push(uid);
        (state, uid)
    };

    let (mut state, uid) = make();
    let counter_before = state.run_rng.combat_card_selection.counter();
    let new_uid = transform_card_to_random_for_hook(&mut state, uid).expect("transforms");

    assert_eq!(
        state.run_rng.combat_card_selection.counter(),
        counter_before + 1,
        "exactly one CombatCardSelection draw per transform",
    );
    // In-place: the new uid sits in the hand at the original slot.
    assert!(
        state.player.hand.contains(&new_uid),
        "replacement is in hand"
    );
    let new_id = state
        .cards
        .iter()
        .find(|c| c.uid == new_uid)
        .unwrap()
        .card_id;
    assert_ne!(
        new_id,
        CardId::StrikeIronclad,
        "basic is not in the transform pool"
    );

    // Determinism: an identical fresh state yields the identical pick.
    let (mut state2, uid2) = make();
    let new_uid2 = transform_card_to_random_for_hook(&mut state2, uid2).expect("transforms");
    let new_id2 = state2
        .cards
        .iter()
        .find(|c| c.uid == new_uid2)
        .unwrap()
        .card_id;
    assert_eq!(
        new_id, new_id2,
        "transform is deterministic under a fixed seed"
    );
}

/// Bead `sts2-rs-p52dg` (gh #6, Entropy transform-pool root): a **Token**-
/// rarity original (the per-combat token cards: GiantRock, Shiv, Soul, the
/// Regent minion cards, …) is FORCED onto the `ColorlessCardPool` by C#
/// `CardFactory.GetDefaultTransformationOptions`
/// (`(Rarity not in {Event,Ancient,Token}) ? original.Pool : Colorless`), so
/// Entropy transforms a hand GIANT_ROCK into a colorless Common/Uncommon/Rare
/// card — NOT a status card. Before the fix GiantRock was mis-tagged `Status`
/// and fell into the StatusCardPool branch (seed 3872: Entropy gave BECKON
/// where C# gives AUTOMATION).
#[test]
fn entropy_transforms_token_original_into_colorless_not_status() {
    use super::helpers::{
        colorless_combat_generatable_card_ids, transform_card_to_random_for_hook,
    };
    use crate::cards::types::CardRarity;

    // The 10 TokenCardPool cards that carry `CardRarity.Token` in the C#
    // decomp (Disintegration / MindRot / Sloth / WasteAway are `Status` and
    // intentionally excluded).
    let token_cards = [
        CardId::GiantRock,
        CardId::Fuel,
        CardId::Luminesce,
        CardId::MinionDiveBomb,
        CardId::MinionSacrifice,
        CardId::MinionStrike,
        CardId::Shiv,
        CardId::Soul,
        CardId::SovereignBlade,
        CardId::SweepingGaze,
    ];
    for id in token_cards {
        assert_eq!(
            crate::cards::spec_index::rarity_for_card_id(id),
            Some(CardRarity::Token),
            "{id:?} must carry Token rarity to match the C# TokenCardPool",
        );
    }

    let colorless_pool: Vec<CardId> = colorless_combat_generatable_card_ids().to_vec();
    let status_ids: Vec<CardId> = crate::cards::spec_index::STATUS_SPECS
        .iter()
        .map(|f| f().id)
        .collect();

    let (mut state, _euid) = fresh_state(CardId::GiantRock, 16, 0);
    state.player.character = Some(sts2_core::potions::CharacterId::Ironclad);
    let uid = sts2_core::CardUid(NonZeroU32::new(1).expect("nz"));
    state.player.play.clear();
    state.player.hand.push(uid);

    let new_uid = transform_card_to_random_for_hook(&mut state, uid).expect("transforms");
    let new_id = state
        .cards
        .iter()
        .find(|c| c.uid == new_uid)
        .unwrap()
        .card_id;

    assert!(
        colorless_pool.contains(&new_id),
        "Token original must transform into a colorless combat-generatable card, got {new_id:?}",
    );
    assert!(
        !status_ids.contains(&new_id),
        "Token original must NOT transform into a status card, got {new_id:?}",
    );
}

