/// ThinkingAhead (`sts2-rs-dfhfr`): the `PutBack` option order is the raw
/// HAND pile order (C# `CardSelectCmd.FromHand` does NO sort — it returns
/// `PileType.Hand.GetPile(player).Cards` filtered, `CardSelectCmd.cs:469`).
/// The harness drains choices by taking option 0, so the option ORDER is
/// the parity surface: a mixed hand must present options in hand-insertion
/// order, NOT sorted by rarity/Entry/uid. Here the hand (after the draw of
/// 2) is `[Anger, Uppercut, Finesse, Finesse]`; the options must match that
/// exact order so option 0 == the first hand card.
#[test]
fn thinking_ahead_putback_option_order_is_raw_hand_order() {
    install_pool();
    let (mut state, _euid) = fresh_state(CardId::ThinkingAhead, 0, 0);

    // Pre-seed the hand in a deliberate order (NOT alphabetical / rarity
    // sorted): Anger (Common) then Uppercut (Uncommon).
    let push_hand = |state: &mut CombatState, card_id: CardId| -> CardUid {
        let raw = u32::try_from(state.cards.len() + 1).expect("fits");
        let uid = sts2_core::CardUid(NonZeroU32::new(raw).expect("nz"));
        state.cards.push(Card {
            uid,
            card_id,
            cost: sts2_core::CardEnergyCost::new(1),
            card_type: CardType::Skill,
            target_type: TargetType::Self_,
            upgraded: false,
            base_damage: 0,
            base_block: 0,
            ..Card::pod_defaults()
        });
        state.player.hand.push(uid);
        uid
    };
    let anger = push_hand(&mut state, CardId::Anger);
    let uppercut = push_hand(&mut state, CardId::Uppercut);
    // Two draw cards drawn in → appended to the END of the hand pile.
    let drawn1 = push_draw_card_id(&mut state, CardId::Finesse);
    let drawn2 = push_draw_card_id(&mut state, CardId::Finesse);

    let _ = lookup(CardId::ThinkingAhead).expect("registered")(&mut state, None);
    let pc = state.pending_choice.as_ref().expect("opens a choice");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::PutBack);
    // Options must mirror raw hand order: pre-existing cards first (in
    // insertion order), then the two drawn cards appended at the tail.
    let opt_uids: Vec<_> = pc.options.iter().map(|o| o.card_uid.unwrap()).collect();
    assert_eq!(
        opt_uids,
        vec![anger, uppercut, drawn1, drawn2],
        "PutBack options are raw hand-pile order (no rarity/Entry/uid sort)",
    );
    // The played ThinkingAhead (on the Play pile) is never an option.
    assert!(
        !opt_uids.contains(&sts2_core::CardUid(NonZeroU32::new(1).expect("nz"))),
        "played card is excluded (Hand->Play before dispatch)",
    );
}

/// ThinkingAhead (`sts2-rs-dfhfr`): when the resulting hand has ≤1 card,
/// C# `FromHand` AUTO-resolves (`CardSelectCmd.cs:475-478`,
/// `list.Count <= MinSelect` with `MinSelect == 1`) — taking the single
/// card with NO prompt — and `OnPlay` then places it on top of the draw
/// pile. We must NOT surface a 1-option choice in that case (same class as
/// Headbutt under `sts2-rs-419n`). Here the hand is empty and exactly one
/// card is drawn, so it auto-lands on draw-top.
#[test]
fn thinking_ahead_single_card_auto_takes_to_draw_top_no_choice() {
    install_pool();
    let (mut state, _euid) = fresh_state(CardId::ThinkingAhead, 0, 0);
    // Exactly one card available to draw (empty hand before draw).
    let only = push_draw_card_id(&mut state, CardId::Finesse);

    let _ = lookup(CardId::ThinkingAhead).expect("registered")(&mut state, None);
    assert!(
        state.pending_choice.is_none(),
        "≤1 hand card auto-takes — no choice surfaced",
    );
    assert!(
        state.player.hand.is_empty(),
        "the single drawn card was moved out of hand",
    );
    assert_eq!(
        state.player.draw.first().copied(),
        Some(only),
        "auto-taken card lands on TOP of the draw pile",
    );
    assert!(
        state.player.pinned_top.contains(&only),
        "auto-taken card is pinned top-of-draw for PIMC re-shuffles",
    );
}

/// ThinkingAhead (`sts2-rs-dfhfr`): resolving the multi-option `PutBack`
/// choice removes the chosen card from hand and inserts it at draw TOP
/// (C# `CardPileCmd.Add(selected, PileType.Draw, CardPilePosition.Top)`,
/// `ThinkingAhead.cs:29`). Picking option 0 puts the first hand card on top.
#[test]
fn thinking_ahead_resolve_places_chosen_on_draw_top() {
    install_pool();
    let (mut state, _euid) = fresh_state(CardId::ThinkingAhead, 0, 0);
    for _ in 0..4 {
        push_draw_card_id(&mut state, CardId::Finesse);
    }
    let _ = lookup(CardId::ThinkingAhead).expect("registered")(&mut state, None);
    let pc = state.pending_choice.as_ref().expect("opens a choice");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::PutBack);
    // Option 0 == first hand card (the harness's pick).
    let chosen = pc.options[0].card_uid.expect("hand option carries uid");

    let selection: smallvec::SmallVec<[u8; 4]> = [0u8].into_iter().collect();
    let res = sts2_core::apply(&mut state, sts2_core::Action::ResolveChoice { selection });
    assert_eq!(res, sts2_core::StepResult::Advanced);
    assert!(state.pending_choice.is_none());
    assert!(
        !state.player.hand.contains(&chosen),
        "chosen card removed from hand",
    );
    assert_eq!(
        state.player.draw.first().copied(),
        Some(chosen),
        "chosen card placed on TOP of the draw pile",
    );
}

/// ThinkingAhead (`sts2-rs-dfhfr`): base version Exhausts the played card,
/// upgrade REMOVES Exhaust (`ThinkingAhead.cs:14` `CanonicalKeywords =
/// Exhaust`, `OnUpgrade` `RemoveKeyword(Exhaust)`). Pinned via the spec +
/// upgrade-delta keywords so the combat-loop play-cleanup routes the played
/// base copy to Exhaust and the upgraded copy to Discard.
#[test]
fn thinking_ahead_base_exhausts_upgrade_drops_exhaust() {
    // Base spec carries the EXHAUST keyword (content-side `CardKeywords`,
    // re-exported via the prelude).
    let base_spec = super::thinking_ahead::spec();
    assert!(
        base_spec
            .keywords
            .contains(crate::cards::types::CardKeywords::EXHAUST),
        "base ThinkingAhead Exhausts",
    );
    // Upgrade delta clears all keywords (drops Exhaust).
    let delta = super::thinking_ahead::upgrade().expect("ThinkingAhead is upgradable");
    assert_eq!(
        delta.keywords,
        Some(crate::cards::types::CardKeywords::NONE),
        "upgrade removes Exhaust (keywords -> NONE)",
    );
}

