/// Jackpot Ironclad pool parity (sts2-rs-gqu3t): the cost-0 candidate pool
/// for Ironclad must contain **10** cards because `DemonicShield` has
/// `MultiplayerConstraint => MultiplayerOnly` (`DemonicShield.cs:15`) and is
/// therefore dropped by C# `FilterForCombat` → `FilterForPlayerCount` in
/// single-player. The prior code sampled from `IRONCLAD_SPECS` filtered by
/// `cost==0` (12 candidates, including DemonicShield), desyncing the
/// `NextInt(0,N)` range vs C#.
///
/// v0.107.1: DrumOfBattle was reworked from a 0-cost Power into a 1-cost
/// Skill, so it left the cost-0 subset — the pool shrank from 11 to 10.
///
/// The 10 cards (alphabetical, matching `ironclad_combat_generatable_specs()`
/// cost-0 subset): Anger, BattleTrance, Bloodletting, Brand, Bully, Offering,
/// PactsEnd, PrimalForce, Rage, Spite.
#[test]
fn jackpot_ironclad_pool_excludes_demonic_shield() {
    use crate::cards::ironclad::specs::ironclad_combat_generatable_specs;
    use crate::cards::types::CardRarity;

    // DemonicShield must NOT appear in the 78-card combat-generatable pool.
    let generatable = ironclad_combat_generatable_specs();
    assert!(
        !generatable.iter().any(|s| s.id == CardId::DemonicShield),
        "DemonicShield (MultiplayerOnly) must be absent from ironclad_combat_generatable_specs"
    );

    // The cost-0 subset (Jackpot's effective pool) must be exactly 10 cards
    // (v0.107.1: DrumOfBattle is now a 1-cost Skill; DemonicShield excluded).
    let cost0: Vec<_> = generatable.iter().filter(|s| s.cost == 0).collect();
    assert_eq!(
        cost0.len(),
        10,
        "Ironclad cost-0 Jackpot pool: expected 10 (v0.107.1, DemonicShield + DrumOfBattle excluded), got {}",
        cost0.len()
    );

    // All generated cards must be eligible: not Basic/Ancient/Event, not
    // MultiplayerOnly (enforced by the 78-card pool membership itself).
    for spec in &cost0 {
        assert!(
            !matches!(
                spec.rarity,
                CardRarity::Basic | CardRarity::Ancient | CardRarity::Event
            ),
            "Cost-0 Jackpot card {:?} has ineligible rarity {:?}",
            spec.id,
            spec.rarity
        );
    }
}

/// TheBomb (sts2-rs-gblko): applies a 3-turn countdown carrying 40 bomb
/// damage; on the 3rd player turn-end it deals 40 (Unpowered) to every
/// enemy and removes itself. Decrements (not detonates) on turns 1 & 2.
#[test]
fn the_bomb_counts_down_then_detonates_all_enemies() {
    use sts2_core::hooks::{dispatch_before_turn_end, TurnSideCtx};
    use sts2_core::powers::PowerKind;
    use sts2_core::Side;
    install_pool();
    let (mut state, _euid) = fresh_state(CardId::TheBombCard, 0, 0);
    add_player_creature(&mut state);
    let _ = lookup(CardId::TheBombCard).expect("registered")(&mut state, None);
    let bomb_amount = |s: &CombatState| {
        s.powers
            .iter()
            .find(|p| p.kind == PowerKind::TheBomb)
            .map(|p| (p.amount, p.counter))
    };
    assert_eq!(
        bomb_amount(&state),
        Some((3, 40)),
        "applied: 3 turns / 40 dmg"
    );
    let enemy_hp0 = state.creatures[0].current_hp;
    let ctx = TurnSideCtx { side: Side::Player };
    // Turn-end 1 & 2: countdown only, no damage.
    dispatch_before_turn_end(&mut state, &ctx);
    assert_eq!(bomb_amount(&state).map(|x| x.0), Some(2));
    dispatch_before_turn_end(&mut state, &ctx);
    assert_eq!(bomb_amount(&state).map(|x| x.0), Some(1));
    assert_eq!(state.creatures[0].current_hp, enemy_hp0, "no damage yet");
    // Turn-end 3: detonate for 40 to all enemies, remove the power.
    dispatch_before_turn_end(&mut state, &ctx);
    assert_eq!(
        enemy_hp0 - state.creatures[0].current_hp,
        40,
        "detonates 40"
    );
    assert_eq!(bomb_amount(&state), None, "power removed after detonation");
}

