#[test]
fn colorless_power_amounts_scale_with_upgrade() {
    use sts2_core::powers::PowerKind;
    install_pool();
    let player_power = |card: CardId, kind: PowerKind, upgraded: bool| -> Option<i32> {
        let (mut state, _euid) = fresh_state(card, 0, 0);
        state.cards[0].upgraded = upgraded;
        let player_id = NonZeroU32::new(99).expect("nz");
        state.creatures.push(Creature {
            id: player_id,
            current_hp: 80,
            max_hp: 80,
            block: 0,
            powers: SmallVec::new(),
            species: None,
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: MonsterId("Player"),
            ai: None,
        });
        state.player.creature_uid = Some(CreatureUid(player_id));
        let _ = lookup(card).expect("registered")(&mut state, None);
        let pc = state
            .creatures
            .iter()
            .find(|c| c.id == player_id)
            .expect("player");
        pc.powers.iter().find_map(|pu| {
            state
                .powers
                .iter()
                .find(|p| p.id == pu.0 && p.kind == kind)
                .map(|p| p.amount)
        })
    };
    let enemy_power = |card: CardId, kind: PowerKind, upgraded: bool| -> Option<i32> {
        let (mut state, euid) = fresh_state(card, 0, 0);
        state.cards[0].upgraded = upgraded;
        let _ = lookup(card).expect("registered")(&mut state, Some(euid));
        state.creatures[0].powers.iter().find_map(|pu| {
            state
                .powers
                .iter()
                .find(|p| p.id == pu.0 && p.kind == kind)
                .map(|p| p.amount)
        })
    };
    // EternalArmor Plating 9->12, Prowess Str/Dex 1->2 (player).
    assert_eq!(
        player_power(CardId::EternalArmor, PowerKind::Plating, false),
        Some(9)
    );
    assert_eq!(
        player_power(CardId::EternalArmor, PowerKind::Plating, true),
        Some(12)
    );
    assert_eq!(
        player_power(CardId::Prowess, PowerKind::Strength, false),
        Some(1)
    );
    assert_eq!(
        player_power(CardId::Prowess, PowerKind::Strength, true),
        Some(2)
    );
    assert_eq!(
        player_power(CardId::Prowess, PowerKind::Dexterity, true),
        Some(2)
    );
    // DarkShackles 9->15, Shockwave Weak/Vuln 3->5 (enemy).
    assert_eq!(
        enemy_power(CardId::DarkShackles, PowerKind::DarkShackles, false),
        Some(9)
    );
    assert_eq!(
        enemy_power(CardId::DarkShackles, PowerKind::DarkShackles, true),
        Some(15)
    );
    // sts2-rs-5aack: DarkShacklesPower : TemporaryStrengthPower
    // (IsPositive=false) folds -StrengthLoss Strength on apply.
    assert_eq!(
        enemy_power(CardId::DarkShackles, PowerKind::Strength, false),
        Some(-9)
    );
    assert_eq!(
        enemy_power(CardId::DarkShackles, PowerKind::Strength, true),
        Some(-15)
    );
    assert_eq!(
        enemy_power(CardId::Shockwave, PowerKind::Weak, false),
        Some(3)
    );
    assert_eq!(
        enemy_power(CardId::Shockwave, PowerKind::Weak, true),
        Some(5)
    );
    assert_eq!(
        enemy_power(CardId::Shockwave, PowerKind::Vulnerable, true),
        Some(5)
    );
}

macro_rules! pin_registered {
    ($name:ident, $variant:ident) => {
        #[test]
        fn $name() {
            install_pool();
            assert!(
                lookup(CardId::$variant).is_some(),
                concat!("CardId::", stringify!($variant), " has no handler")
            );
        }
    };
}

