/// Push a player mirror Creature and link it, returning its uid. Mirrors
/// the inline setup used by the TheGambit/Fisticuffs tests.
fn push_player(state: &mut CombatState) -> CreatureUid {
    let player_id = NonZeroU32::new(99).expect("nz");
    state.creatures.push(Creature {
        id: player_id,
        current_hp: 80,
        max_hp: 80,
        block: 0,
        powers: SmallVec::new(),
        species: None,
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Player"),
        ai: None,
    });
    let uid = CreatureUid(player_id);
    state.player.creature_uid = Some(uid);
    uid
}

fn enemy_hp(state: &CombatState, enemy: CreatureUid) -> i32 {
    state
        .creatures
        .iter()
        .find(|c| c.id == enemy.0)
        .map(|c| c.current_hp)
        .expect("enemy present")
}

fn creature_power(state: &CombatState, who: CreatureUid, kind: PowerKind) -> i32 {
    let creature = state
        .creatures
        .iter()
        .find(|c| c.id == who.0)
        .expect("creature");
    creature
        .powers
        .iter()
        .find_map(|uid| {
            state
                .powers
                .iter()
                .find(|p| p.id == uid.0 && p.kind == kind)
                .map(|p| p.amount)
        })
        .unwrap_or(0)
}

