/// `sts2-rs-y9hvo`: Discovery opens a generate-3 + choose-1 skippable
/// screen (C# `GetDistinctForCombat(pool, 3)` → `FromChooseACardScreen(
/// canSkip: true)`). The `AddGeneratedFreeToHand` resolver — shared with
/// the Skill/Power/Attack potions and exercised by their tests — then
/// stamps the chosen card `FREE_THIS_TURN` (C# `Discovery.cs:35`
/// `SetToFreeThisTurn`) and moves it to hand.
#[test]
fn y9hvo_discovery_flags_generated_card_free_this_turn() {
    use sts2_core::potions::CharacterId;
    install_pool();
    let (mut state, _enemy) = fresh_state(CardId::Discovery, 0, 0);
    let _ = push_player(&mut state);
    state.player.character = Some(CharacterId::Ironclad);
    let hand_before = state.player.hand.len();
    let f = lookup(CardId::Discovery).expect("registered");
    f(&mut state, None);
    let pc = state
        .pending_choice
        .as_ref()
        .expect("Discovery opens a choose-a-card screen");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::AddGeneratedFreeToHand);
    assert_eq!((pc.min_select, pc.max_select), (1, 1), "single pick");
    assert!(pc.can_skip, "C# canSkip: true");
    assert_eq!(pc.options.len(), 3, "GetDistinctForCombat(pool, 3)");
    assert_eq!(
        state.player.hand.len(),
        hand_before,
        "no spawn before the choice resolves — only the chosen id materialises"
    );
}

