fn colorless_self_power_amounts_scale_with_upgrade() {
    use sts2_core::powers::PowerKind;
    install_pool();
    let amount = |card: CardId, kind: PowerKind, upgraded: bool| -> i32 {
        let (mut state, _enemy) = fresh_state(card, 0, 0);
        state.cards[0].upgraded = upgraded;
        let player_id = NonZeroU32::new(99).expect("nz");
        state.creatures.push(Creature {
            id: player_id,
            current_hp: 80,
            max_hp: 80,
            block: 0,
            powers: SmallVec::new(),
            species: None,
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: MonsterId("Player"),
            ai: None,
        });
        state.player.creature_uid = Some(CreatureUid(player_id));
        let f = lookup(card).expect("registered");
        f(&mut state, None);
        state
            .creatures
            .iter()
            .find(|c| c.id == player_id)
            .expect("player mirror")
            .powers
            .iter()
            .find_map(|uid| {
                state
                    .powers
                    .iter()
                    .find(|p| p.id == uid.0 && p.kind == kind)
                    .map(|p| p.amount)
            })
            .unwrap_or(0)
    };
    for (card, kind, base, up) in [
        (CardId::Caltrops, PowerKind::Thorns, 3, 5),
        (CardId::FeedingFrenzyCard, PowerKind::FeedingFrenzy, 5, 7),
        (CardId::Fasten, PowerKind::Fasten, 4, 6),
        (CardId::PanacheCard, PowerKind::Panache, 10, 14),
        (CardId::PrepTime, PowerKind::PrepTime, 4, 6),
    ] {
        assert_eq!(amount(card, kind, false), base, "{kind:?} base");
        assert_eq!(amount(card, kind, true), up, "{kind:?} upgraded");
    }
    // sts2-rs-ay9kr: FeedingFrenzyPower : TemporaryStrengthPower
    // (IsPositive=true) folds +amount Strength on apply alongside
    // the FeedingFrenzy marker.
    assert_eq!(
        amount(CardId::FeedingFrenzyCard, PowerKind::Strength, false),
        5
    );
    assert_eq!(
        amount(CardId::FeedingFrenzyCard, PowerKind::Strength, true),
        7
    );
}

