#[test]
fn play_apotheosis_upgrades_every_combat_card_except_self() {
    use sts2_core::cards::{Card, CardType, TargetType};
    use sts2_core::CardUid;
    install_pool();
    let (mut state, _euid) = fresh_state(CardId::Apotheosis, 0, 0);
    let push_to = |state: &mut CombatState, pile: &str| -> CardUid {
        let raw = u32::try_from(state.cards.len() + 1).unwrap();
        let uid = CardUid(NonZeroU32::new(raw).unwrap());
        state.cards.push(Card {
            uid,
            card_id: CardId::StrikeIronclad,
            cost: sts2_core::CardEnergyCost::new(1),
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 6,
            base_block: 0,
            ..Card::pod_defaults()
        });
        match pile {
            "hand" => state.player.hand.push(uid),
            "draw" => state.player.draw.push(uid),
            "discard" => state.player.discard.push(uid),
            "exhaust" => state.player.exhaust.push(uid),
            _ => unreachable!(),
        }
        uid
    };
    let hand_uid = push_to(&mut state, "hand");
    let draw_uid = push_to(&mut state, "draw");
    let discard_uid = push_to(&mut state, "discard");
    let exhaust_uid = push_to(&mut state, "exhaust");
    let played = *state.player.play.last().unwrap();

    let f = lookup(CardId::Apotheosis).expect("registered");
    f(&mut state, None);

    let upgraded = |state: &CombatState, uid: CardUid| -> bool {
        let idx = uid.0.get() as usize - 1;
        state.cards[idx].upgraded
    };
    assert!(upgraded(&state, hand_uid), "hand card upgraded");
    assert!(upgraded(&state, draw_uid), "draw card upgraded");
    assert!(upgraded(&state, discard_uid), "discard card upgraded");
    assert!(upgraded(&state, exhaust_uid), "exhaust card upgraded");
    assert!(
        !upgraded(&state, played),
        "Apotheosis itself stays unupgraded"
    );
}

