/// CalamityPower listener (bead `sts2-rs-q6bix`): C#
/// `CalamityPower.AfterCardPlayed` conjures `Amount` random Attacks (C#
/// `GetForCombat` — uniform per-slot pick over the FilterForCombat'd
/// attack pool, WITH replacement) into hand each time the owner plays an
/// Attack. With 1 Calamity stack, playing one Attack must generate exactly
/// 1 attack into hand and consume exactly 1 `combat_card_generation` read.
/// Requires the full registry (`ensure_installed`) so the with-replacement
/// sampler trampoline is registered. Reproduces the coverage-sweep
/// `combat_card_generation csharp=1 rust=0` desync the listener fixed.
#[test]
fn calamity_generates_one_attack_into_hand_on_attack_played() {
    use sts2_core::card_effects::apply_power_to_creature;
    crate::cards::dispatch::ensure_installed();
    let mut state = CombatState {
        rng: sts2_core::dotnet_rng::Rng::new(0_i32),
        ..Default::default()
    };
    add_player_creature(&mut state);
    state.player.character = Some(sts2_core::CharacterId::Ironclad);
    let puid = state.player.creature_uid.expect("player mirror");
    apply_power_to_creature(&mut state, puid, sts2_core::powers::PowerKind::Calamity, 1);
    let gen_before = state.run_rng.combat_card_generation.counter();
    let hand_before = state.player.hand.len();
    let ctx = sts2_core::hooks::CardCtx {
        card_type: Some(CardType::Attack),
        ..Default::default()
    };
    sts2_core::hooks::dispatch_before_card_played_powers(&mut state, 1, false);
    sts2_core::hooks::dispatch_after_card_played(&mut state, &ctx);
    assert_eq!(
        state.player.hand.len(),
        hand_before + 1,
        "1 Calamity stack ⇒ 1 generated attack into hand"
    );
    assert_eq!(
        state.run_rng.combat_card_generation.counter(),
        gen_before + 1,
        "GetForCombat with-replacement amount=1 ⇒ exactly 1 combat_card_generation read"
    );
}

/// C# `CalamityPower` records the Attack at `BeforeCardPlayed` and conjures
/// only if `AfterCardPlayed` can remove it (CalamityPower.cs:23-54).
/// `Hook.BeforeCardPlayed` is skipped once the combat `IsOverOrEnding`, the
/// after hook is not — so a play whose Before never fired (a replay after the
/// last enemy died) conjures nothing (Defect random-loadout v0.107.1 seed 1025).
#[test]
fn calamity_conjures_nothing_when_before_card_played_was_skipped() {
    use sts2_core::card_effects::apply_power_to_creature;
    crate::cards::dispatch::ensure_installed();
    let mut state = CombatState {
        rng: sts2_core::dotnet_rng::Rng::new(0_i32),
        ..Default::default()
    };
    add_player_creature(&mut state);
    state.player.character = Some(sts2_core::CharacterId::Ironclad);
    let puid = state.player.creature_uid.expect("player mirror");
    apply_power_to_creature(&mut state, puid, sts2_core::powers::PowerKind::Calamity, 1);
    let ctx = sts2_core::hooks::CardCtx {
        card_type: Some(CardType::Attack),
        ..Default::default()
    };
    // Armed play conjures once; the next play's Before is skipped.
    sts2_core::hooks::dispatch_before_card_played_powers(&mut state, 1, false);
    sts2_core::hooks::dispatch_after_card_played(&mut state, &ctx);
    let hand_after_first = state.player.hand.len();
    let gen = state.run_rng.combat_card_generation.counter();
    sts2_core::hooks::dispatch_after_card_played(&mut state, &ctx);
    assert_eq!(state.player.hand.len(), hand_after_first);
    assert_eq!(state.run_rng.combat_card_generation.counter(), gen);
}

/// C# `CardPileCmd.Add` returns `success = false` before touching a combat
/// pile once `CombatManager.IsEnding` (CardPileCmd.cs:312 v0.107.1, :379
/// v0.111.0). So a Calamity Attack conjured after the play killed the last
/// enemy never reaches the hand; its generation roll still happens. Loadout
/// Ironclad 5625 v0.111.0: Stampede's next pick saw an empty hand in C# and
/// rolled nothing.
#[test]
fn calamity_attack_conjured_after_the_last_kill_stays_out_of_the_hand() {
    use sts2_core::card_effects::apply_power_to_creature;
    crate::cards::dispatch::ensure_installed();
    for version in [
        sts2_core::GameVersion::V0_107_1,
        sts2_core::GameVersion::V0_111_0,
    ] {
        let (mut state, enemy) = fresh_state(CardId::StrikeIronclad, 6, 0);
        state.game_version = version;
        state.player.play.clear();
        add_player_creature(&mut state);
        state.player.character = Some(sts2_core::CharacterId::Ironclad);
        let puid = state.player.creature_uid.expect("player mirror");
        apply_power_to_creature(&mut state, puid, sts2_core::powers::PowerKind::Calamity, 1);
        let ctx = sts2_core::hooks::CardCtx {
            card_type: Some(CardType::Attack),
            ..Default::default()
        };
        sts2_core::hooks::dispatch_before_card_played_powers(&mut state, 1, false);
        // The play kills the last enemy.
        if let Some(c) = state.creatures.iter_mut().find(|c| c.id == enemy.0) {
            c.current_hp = 0;
        }
        assert!(sts2_core::combat_loop::combat_is_ending(&state));
        let gen_before = state.run_rng.combat_card_generation.counter();
        let hand_before = state.player.hand.len();
        sts2_core::hooks::dispatch_after_card_played(&mut state, &ctx);
        assert_eq!(
            state.run_rng.combat_card_generation.counter(),
            gen_before + 1,
            "{version:?}: the Attack is still generated"
        );
        assert_eq!(
            state.player.hand.len(),
            hand_before,
            "{version:?}: not added"
        );
        assert!(state.player.discard.is_empty(), "{version:?}");
    }
}

/// C# `Hook.AfterCardPlayed` walks `CombatState.IterateHookListeners`
/// (CombatState.cs:115-170): the player's Powers first, then the player's
/// relics, then each enemy's Powers. So the player's `CalamityPower` card
/// lands in hand BEFORE the Wither added by the enemy-owned (Aeonglass)
/// `WitheringPresencePower`. Rust used to fire Calamity in the late commutative
/// `pending` lane, after the WitheringPresence lane, swapping the two hand
/// slots (GH #1054, Necrobinder-3005-a0-act2#b3: C# hand [.., SNAP, WITHER]).
#[test]
fn calamity_card_lands_before_withering_presence_wither() {
    use sts2_core::card_effects::apply_power_to_creature;
    crate::cards::dispatch::ensure_installed();
    let mut state = CombatState {
        rng: sts2_core::dotnet_rng::Rng::new(0_i32),
        ..Default::default()
    };
    state.player.current_hp = 70;
    state.player.max_hp = 70;
    state.init_player_creature();
    state.player.character = Some(sts2_core::CharacterId::Ironclad);
    let _boss = state.spawn_enemy(MonsterKind::Aeonglass);
    // One card short of the WitheringPresence Wither (countdown on `counter`).
    let wp = state
        .powers
        .iter_mut()
        .find(|p| p.kind == sts2_core::powers::PowerKind::WitheringPresence)
        .expect("Aeonglass spawns with WitheringPresence");
    wp.counter = wp.amount - 1;
    let puid = state.player.creature_uid.expect("player mirror");
    apply_power_to_creature(&mut state, puid, sts2_core::powers::PowerKind::Calamity, 1);
    let hand_before = state.player.hand.len();
    let ctx = sts2_core::hooks::CardCtx {
        card_type: Some(CardType::Attack),
        ..Default::default()
    };
    sts2_core::hooks::dispatch_before_card_played_powers(&mut state, 1, false);
    // The card-play pipeline order (`combat_loop::dispatch_after_card_played_buses`
    // minus the relic bus, which holds no relics here).
    sts2_core::hooks::dispatch_after_card_played_ordered_enemy_hits(&mut state, &ctx);
    sts2_core::hooks::dispatch_after_card_played_player_lanes(&mut state, &ctx);
    sts2_core::hooks::dispatch_after_card_played_other_creatures(&mut state, &ctx);
    let added: Vec<_> = state.player.hand[hand_before..]
        .iter()
        .map(|uid| {
            state
                .cards
                .get(uid.0.get() as usize - 1)
                .expect("card")
                .card_id
        })
        .collect();
    assert_eq!(
        added.len(),
        2,
        "one Calamity attack + one Wither: {added:?}"
    );
    assert_ne!(
        added[0],
        sts2_core::cards::CardId::Wither,
        "the Calamity attack comes first: {added:?}"
    );
    assert_eq!(
        added[1],
        sts2_core::cards::CardId::Wither,
        "the enemy-power Wither comes after the player-power card: {added:?}"
    );
}

/// OrangeDough (Regent Rare relic) — `AfterSideTurnStart` on round 1 generates
/// 2 DISTINCT colorless cards into hand via C#
/// `CardFactory.GetDistinctForCombat(Owner, ColorlessCardPool, 2,
/// Rng.CombatCardGeneration)` — a whole-pool `UnstableShuffle` over the
/// `combat_card_generation` stream. The earlier port used the with-replacement
/// `sample_colorless_cards` (drawn off the `combat` stream from the
/// Python-derived `COLORLESS_SPECS` pool), consuming ZERO
/// `combat_card_generation` reads and picking the wrong cards (Regent coverage
/// seed 93: hand_ids[5] cs=EQUILIBRIUM rs=PRODUCTION, combat_card_generation
/// cs=49 rs=0). This locks the distinct-sampler wiring: 2 cards into hand AND
/// the `combat_card_generation` cursor advances (an `UnstableShuffle` over the
/// >2-card colorless pool reads pool-len-1 ints). Bead `sts2-rs-7xih`.
#[test]
fn orange_dough_generates_two_distinct_colorless_into_hand_via_card_generation() {
    crate::cards::dispatch::install_default_registry();
    sts2_core::relic_effects::install_default_registry();
    let mut state = CombatState {
        rng: sts2_core::dotnet_rng::Rng::new(0_i32),
        ..Default::default()
    };
    add_player_creature(&mut state);
    state.player.character = Some(sts2_core::CharacterId::Regent);
    // Round 1 (the relic's `RoundNumber <= 1` gate); player side.
    state.round = 1;
    state.relics.push(sts2_core::Relic {
        id: NonZeroU32::new(1).expect("nz"),
        kind: sts2_core::RelicKind::OrangeDough,
        counter: 0,
        is_wax: false,
        is_melted: false,
    });
    let gen_before = state.run_rng.combat_card_generation.counter();
    let hand_before = state.player.hand.len();

    let result = sts2_core::relic_effects::dispatch_after_side_turn_start(
        &mut state,
        sts2_core::Side::Player,
    );
    assert_eq!(result, sts2_core::EffectResult::Resolved);

    // Two cards landed in hand.
    assert_eq!(
        state.player.hand.len(),
        hand_before + 2,
        "OrangeDough generates exactly 2 cards into hand"
    );
    // Both are distinct (C# GetDistinctForCombat) and colorless cards.
    let new_ids: Vec<CardId> = state.player.hand[hand_before..]
        .iter()
        .map(|uid| state.cards[uid.0.get() as usize - 1].card_id)
        .collect();
    assert_ne!(
        new_ids[0], new_ids[1],
        "GetDistinctForCombat ⇒ distinct cards"
    );
    for id in &new_ids {
        assert!(
            crate::cards::spec_index::COLORLESS_SPECS
                .iter()
                .any(|f| f().id == *id),
            "generated card {id:?} must be a colorless card"
        );
    }
    // The fix: the draw runs off the `combat_card_generation` stream (a
    // whole-pool UnstableShuffle reads pool-len-1 ints), NOT the with-
    // replacement `combat` stream that left this cursor at 0.
    assert!(
        state.run_rng.combat_card_generation.counter() > gen_before,
        "GetDistinctForCombat consumes the combat_card_generation stream \
         (was 0 with the with-replacement sampler)"
    );
}

#[test]
fn play_dual_wield_clones_leftmost_attack_or_power() {
    use sts2_core::cards::{Card, CardType, TargetType};
    use sts2_core::CardUid;
    install_pool();
    let (mut state, _euid) = fresh_state(CardId::DualWield, 0, 0);
    // Seed hand with a Skill (non-clonable), a Power (target), and an
    // Attack — the Power should be picked because it comes first.
    let push_card = |state: &mut CombatState, ct: CardType| -> CardUid {
        let raw = u32::try_from(state.cards.len() + 1).unwrap();
        let uid = CardUid(NonZeroU32::new(raw).unwrap());
        state.cards.push(Card {
            uid,
            card_id: CardId::StrikeIronclad,
            cost: sts2_core::CardEnergyCost::new(1),
            card_type: ct,
            target_type: TargetType::Self_,
            upgraded: false,
            base_damage: 0,
            base_block: 0,
            ..Card::pod_defaults()
        });
        state.player.hand.push(uid);
        uid
    };
    let _skill_uid = push_card(&mut state, CardType::Skill);
    let power_uid = push_card(&mut state, CardType::Power);
    let _attack_uid = push_card(&mut state, CardType::Attack);
    let hand_before = state.player.hand.len();
    let cards_before = state.cards.len();
    let f = lookup(CardId::DualWield).expect("registered");
    f(&mut state, None);
    assert_eq!(
        state.player.hand.len(),
        hand_before + 1,
        "DualWield adds one clone to hand"
    );
    assert_eq!(state.cards.len(), cards_before + 1, "one new card minted");
    let cloned_idx = state.cards.len() - 1;
    assert_eq!(
        state.cards[cloned_idx].card_type,
        state.cards[power_uid.0.get() as usize - 1].card_type,
        "clone matches the picked Power card type"
    );
}

