/// v0.107.1 NeowsFury: deals 10 damage, then opens a `min 0 / max 2`
/// `AddFromDiscardToHand` PLAYER choice over the discard pile (C#
/// `CardSelectCmd.FromCombatPile(Discard, prefs(prompt, 0, num))`). Resolving
/// it returns the chosen cards to hand. The v0.103.2 random `TakeRandom`
/// auto-recycle is gone.
#[test]
fn play_neows_fury_deals_damage_then_opens_discard_choice() {
    use sts2_core::CardUid;
    install_pool();
    let (mut state, euid) = fresh_state(CardId::NeowsFury, 10, 0);
    // Four real cards in the discard pile.
    for n in 10..=13u32 {
        let uid = CardUid(NonZeroU32::new(n).expect("nz"));
        state.cards.push(Card {
            uid,
            card_id: CardId::StrikeIronclad,
            cost: sts2_core::CardEnergyCost::new(1),
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 6,
            base_block: 0,
            ..Card::pod_defaults()
        });
        state.player.discard.push(uid);
    }
    let discard_before = state.player.discard.len();
    let hand_before = state.player.hand.len();
    let hp_before = state.creatures[0].current_hp;
    let f = lookup(CardId::NeowsFury).expect("registered");
    f(&mut state, Some(euid));
    assert_eq!(
        state.creatures[0].current_hp,
        hp_before - 10,
        "NeowsFury deals 10 damage"
    );
    let pc = state
        .pending_choice
        .as_ref()
        .expect("discard choice opened");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::AddFromDiscardToHand);
    assert_eq!(pc.options.len(), 4, "all discards selectable");
    assert_eq!(pc.min_select, 0, "may take 0..num");
    assert_eq!(pc.max_select, 2, "base NeowsFury returns up to 2");
    assert_eq!(
        state.player.hand.len(),
        hand_before,
        "nothing moved until the choice resolves"
    );

    // The two selectable picks are discard[0], discard[1] (uids 10, 11).
    let pick0 = CardUid(NonZeroU32::new(10).expect("nz"));
    let pick1 = CardUid(NonZeroU32::new(11).expect("nz"));
    let _ = discard_before; // count is polluted by the played card routing below.

    // Resolve → return the two chosen discards to hand.
    let mut sel: smallvec::SmallVec<[u8; 4]> = smallvec::SmallVec::new();
    sel.push(0);
    sel.push(1);
    let _ = sts2_core::apply(
        &mut state,
        sts2_core::Action::ResolveChoice { selection: sel },
    );
    assert_eq!(
        state.player.hand.len(),
        hand_before + 2,
        "two cards returned to hand"
    );
    assert!(
        state.player.hand.contains(&pick0) && state.player.hand.contains(&pick1),
        "both chosen discards moved to hand"
    );
    assert!(
        !state.player.discard.contains(&pick0) && !state.player.discard.contains(&pick1),
        "both chosen discards removed from the discard pile"
    );

    // Empty discard: just deals damage, no choice, no panic.
    let (mut state, euid) = fresh_state(CardId::NeowsFury, 10, 0);
    let f = lookup(CardId::NeowsFury).expect("registered");
    f(&mut state, Some(euid));
    assert!(
        state.pending_choice.is_none(),
        "no choice for empty discard"
    );
    assert!(
        state.player.hand.is_empty(),
        "Empty discard -> no cards in hand"
    );
}

