fn play_shockwave_aoes_weak_and_vulnerable_three() {
    use sts2_core::powers::PowerKind;
    install_pool();
    let (mut state, _euid) = fresh_state(CardId::Shockwave, 0, 0);
    // Add a second enemy so AOE behaviour is observable.
    let second_id = NonZeroU32::new(2).expect("nz");
    state.creatures.push(Creature {
        id: second_id,
        current_hp: 50,
        max_hp: 50,
        block: 0,
        powers: SmallVec::new(),
        species: Some(MonsterKind::Nibbit),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Nibbit"),
        ai: None,
    });
    state.enemy_uids.push(CreatureUid(second_id));
    let f = lookup(CardId::Shockwave).expect("registered");
    f(&mut state, None);
    for uid in state.enemy_uids.clone() {
        let creature = state
            .creatures
            .iter()
            .find(|c| c.id == uid.0)
            .expect("enemy alive");
        let weak = creature
            .powers
            .iter()
            .find_map(|p_uid| {
                state
                    .powers
                    .iter()
                    .find(|p| p.id == p_uid.0 && p.kind == PowerKind::Weak)
                    .map(|p| p.amount)
            })
            .expect("Weak stacked");
        let vuln = creature
            .powers
            .iter()
            .find_map(|p_uid| {
                state
                    .powers
                    .iter()
                    .find(|p| p.id == p_uid.0 && p.kind == PowerKind::Vulnerable)
                    .map(|p| p.amount)
            })
            .expect("Vulnerable stacked");
        assert_eq!(weak, 3, "enemy {} Weak amount", uid.0);
        assert_eq!(vuln, 3, "enemy {} Vulnerable amount", uid.0);
    }
}

