/// Bead `sts2-rs-5r2xn`: Master of Strategy draws 3 (4 upgraded) per
/// C# `MasterOfStrategy.cs` CardsVar(3) + OnUpgrade +1. Prior body
/// hardcoded 3.
#[test]
fn master_of_strategy_draw_count_scales_with_upgrade() {
    install_pool();
    for (upgraded, expected) in [(false, 3usize), (true, 4usize)] {
        let (mut state, _) = fresh_state(CardId::MasterOfStrategy, 0, 0);
        state.cards[0].upgraded = upgraded;
        // Seed 5 cards into the draw pile (more than the draw count).
        for _ in 0..5 {
            let raw = u32::try_from(state.cards.len() + 1).expect("fits");
            let uid = CardUid::new(raw).expect("nz");
            let mut card = card_from_spec(&crate::cards::ironclad::strike_ironclad::spec());
            card.uid = uid;
            state.cards.push(card);
            state.player.draw.push(uid);
        }
        let f = lookup(CardId::MasterOfStrategy).expect("registered");
        f(&mut state, None);
        assert_eq!(
            state.player.hand.len(),
            expected,
            "MasterOfStrategy upgraded={upgraded} draws {expected}"
        );
    }
}

