/// Impatience with no attacks in hand: draws 2 cards. Mirrors
/// `colorless.py::impatience` at pin `01c094d`.
#[test]
fn play_impatience_no_attack_draws_two() {
    install_pool();
    let (mut state, _) = fresh_state(CardId::Impatience, 0, 0);
    // Seed a SKILL in hand (so a non-attack exists but no attack).
    let held = sts2_core::CardUid::new(2).expect("nz");
    state.cards.push(Card {
        uid: held,
        card_id: CardId::DefendIronclad,
        cost: sts2_core::CardEnergyCost::new(1),
        card_type: CardType::Skill,
        target_type: TargetType::Self_,
        upgraded: false,
        base_damage: 0,
        base_block: 5,
        ..Card::pod_defaults()
    });
    state.player.hand.push(held);
    // Seed 3 cards in draw pile.
    for raw in 3..=5u32 {
        let cuid = sts2_core::CardUid::new(raw).expect("nz");
        state.cards.push(Card {
            uid: cuid,
            card_id: CardId::StrikeIronclad,
            cost: sts2_core::CardEnergyCost::new(1),
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 6,
            base_block: 0,
            ..Card::pod_defaults()
        });
        state.player.draw.push(cuid);
    }
    let hand_before = state.player.hand.len();
    let f = lookup(CardId::Impatience).expect("registered");
    let _ = f(&mut state, None);
    assert_eq!(state.player.hand.len(), hand_before + 2, "drew 2 cards");
}

