fn play_fisticuffs_gains_block_including_overkill() {
    install_pool();
    let (mut state, enemy) = fresh_state(CardId::Fisticuffs, 7, 0);
    // Drop the target to 3 HP so a 7-damage hit overkills by 4.
    if let Some(c) = state.creatures.iter_mut().find(|c| c.id == enemy.0) {
        c.current_hp = 3;
    }
    let player_id = NonZeroU32::new(99).expect("nz");
    state.creatures.push(Creature {
        id: player_id,
        current_hp: 80,
        max_hp: 80,
        block: 0,
        powers: SmallVec::new(),
        species: None,
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Player"),
        ai: None,
    });
    state.player.creature_uid = Some(CreatureUid(player_id));
    let f = lookup(CardId::Fisticuffs).expect("registered");
    f(&mut state, Some(enemy));
    let enemy_hp = state
        .creatures
        .iter()
        .find(|c| c.id == enemy.0)
        .map(|c| c.current_hp)
        .expect("enemy present");
    assert!(enemy_hp <= 0, "Fisticuffs killed the 3-HP target");
    assert_eq!(
        state.player.block, 7,
        "Fisticuffs gains Block = full damage (7) incl. overkill, not clamped HP-loss (3)"
    );
}

/// Base case: against a full-HP, no-Block enemy Fisticuffs gains Block equal
/// to the damage it dealt (7). C# `Fisticuffs.cs:32`
/// `Sum(r => r.TotalDamage + r.OverkillDamage)` with `BlockedDamage = 0`,
/// `OverkillDamage = 0`, `UnblockedDamage = 7`. Bead `sts2-rs-6cnok`.
#[test]
fn play_fisticuffs_gains_block_equal_to_damage_dealt() {
    install_pool();
    let (mut state, enemy) = fresh_state(CardId::Fisticuffs, 7, 0);
    let _ = push_player(&mut state);
    let f = lookup(CardId::Fisticuffs).expect("registered");
    f(&mut state, Some(enemy));
    assert_eq!(
        enemy_hp(&state, enemy),
        93,
        "7 damage dealt to the 100-HP target"
    );
    assert_eq!(
        state.player.block, 7,
        "Fisticuffs gains Block = damage dealt (7)"
    );
}

/// Block-absorption case: C# `DamageResult.TotalDamage = BlockedDamage +
/// UnblockedDamage` (`DamageResult.cs:17`), so Fisticuffs'
/// `Sum(TotalDamage + OverkillDamage)` includes the portion soaked into the
/// enemy's Block. A 7-damage hit on an enemy with 4 Block deals 3 to HP but
/// still credits the full 7 Block to the player. Bead `sts2-rs-6cnok`.
#[test]
fn play_fisticuffs_block_includes_block_absorbed_damage() {
    install_pool();
    let (mut state, enemy) = fresh_state(CardId::Fisticuffs, 7, 0);
    // Give the enemy 4 Block: 4 of the 7 damage is absorbed, 3 hits HP.
    if let Some(c) = state.creatures.iter_mut().find(|c| c.id == enemy.0) {
        c.block = 4;
    }
    let _ = push_player(&mut state);
    let f = lookup(CardId::Fisticuffs).expect("registered");
    f(&mut state, Some(enemy));
    assert_eq!(
        enemy_hp(&state, enemy),
        97,
        "3 of 7 damage reaches HP (4 absorbed by Block)"
    );
    assert_eq!(
        state.player.block, 7,
        "Fisticuffs Block = TotalDamage (blocked 4 + hp-loss 3) = 7, not just the 3 that hit HP"
    );
}

/// Combined case: Block-absorbed AND overkill on the same hit. Enemy has
/// 2 Block and 2 HP; a 7-damage hit absorbs 2 into Block, deals 2 to HP
/// (kill), and overkills by 3. C# Block = `Sum(TotalDamage + OverkillDamage)`
/// = `(BlockedDamage 2 + UnblockedDamage 2) + OverkillDamage 3` = 7.
/// Bead `sts2-rs-6cnok`.
#[test]
fn play_fisticuffs_block_includes_both_block_absorb_and_overkill() {
    install_pool();
    let (mut state, enemy) = fresh_state(CardId::Fisticuffs, 7, 0);
    if let Some(c) = state.creatures.iter_mut().find(|c| c.id == enemy.0) {
        c.block = 2;
        c.current_hp = 2;
    }
    let _ = push_player(&mut state);
    let f = lookup(CardId::Fisticuffs).expect("registered");
    f(&mut state, Some(enemy));
    assert!(enemy_hp(&state, enemy) <= 0, "2-HP target killed");
    assert_eq!(
        state.player.block, 7,
        "Block = blocked 2 + hp-loss 2 + overkill 3 = full 7"
    );
}

