/// ToricToughness: gains `base_block` (5) AND applies `ToricToughnessPower`
/// (`amount` = Turns = 2, `counter` = stored block = 5). On each turn-start
/// block-clear the power re-grants the stored block (Unpowered) and decrements
/// its turn counter, lasting exactly `Turns` re-grants then removing itself.
/// Bead `sts2-rs-toric-power` (whole-run parity seed RP20: the block must carry
/// across turns or the player takes more damage than C#).
#[test]
fn play_toric_toughness_applies_power_and_retains_block_across_turns() {
    use sts2_core::powers::PowerKind;
    install_pool();
    let (mut state, _e) = fresh_state(CardId::ToricToughness, 0, 5);
    add_player_creature(&mut state);

    let f = lookup(CardId::ToricToughness).expect("registered");
    f(&mut state, None);

    // Immediate block gain on play.
    assert_eq!(state.player.block, 5, "gains base_block on play");
    // Power applied: amount = Turns (2), counter = stored block (5).
    let pow = state
        .powers
        .iter()
        .find(|p| p.kind == PowerKind::ToricToughness)
        .expect("ToricToughnessPower applied");
    assert_eq!(pow.amount, 2, "stack = Turns (2)");
    assert_eq!(pow.counter, 5, "counter stores the block to re-grant");
    let ctx = sts2_core::hooks::BlockClearedCtx {
        cleared: Some(sts2_core::hooks::CreatureRef::Player),
    };
    // Turn 2 start: block clears, AfterBlockCleared re-grants 5 + decrements.
    state.player.block = 0;
    sts2_core::hooks::dispatch_after_block_cleared(&mut state, &ctx);
    assert_eq!(
        state.player.block, 5,
        "re-grants stored block at the next turn start"
    );
    assert_eq!(
        state
            .powers
            .iter()
            .find(|p| p.kind == PowerKind::ToricToughness)
            .map(|p| p.amount),
        Some(1),
        "Turns counter decremented to 1",
    );

    // Turn 3 start: re-grant again, decrement to 0 → power removed.
    state.player.block = 0;
    sts2_core::hooks::dispatch_after_block_cleared(&mut state, &ctx);
    assert_eq!(
        state.player.block, 5,
        "re-grants on the 2nd retained turn too"
    );
    assert!(
        !state
            .powers
            .iter()
            .any(|p| p.kind == PowerKind::ToricToughness),
        "power removed once Turns re-grants are exhausted",
    );

    // Turn 4 start: power gone → no further re-grant.
    state.player.block = 0;
    sts2_core::hooks::dispatch_after_block_cleared(&mut state, &ctx);
    assert_eq!(state.player.block, 0, "no block once the power expired");
}

