// ---- Deep pin: Apotheosis ----
/// Apotheosis = "Upgrade ALL cards in hand for combat." The upgrade
/// machinery (P7) is not wired in this bead; the handler is a marker.
/// This pin locks (a) the spec (cost 2, Innate+Exhaust), (b) that the
/// handler is registered, and (c) that playing it on a populated hand
/// is a no-op (no panics, hand size unchanged, no damage dealt).
#[test]
fn apotheosis_deep_pin_upgrade_all_in_hand() {
    install_pool();
    let s = sspecs::apotheosis();
    assert_eq!(s.cost, 2);
    assert!(s
        .keywords
        .contains(super::super::types::CardKeywords::INNATE));
    assert!(s
        .keywords
        .contains(super::super::types::CardKeywords::EXHAUST));

    // Build a hand of 3 cards + Apotheosis as the resolving card.
    let (mut state, _) = fresh_state(CardId::Apotheosis, 0, 0);
    for raw in 2..=4u32 {
        let cuid = NonZeroU32::new(raw).expect("nz");
        state.cards.push(Card {
            uid: sts2_core::CardUid(cuid),
            card_id: CardId::StrikeIronclad,
            cost: sts2_core::CardEnergyCost::new(1),
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 6,
            base_block: 0,
            ..Card::pod_defaults()
        });
        state.player.hand.push(sts2_core::CardUid(cuid));
    }
    let hand_len = state.player.hand.len();
    let f = lookup(CardId::Apotheosis).expect("registered");
    let r = f(&mut state, None);
    assert_eq!(r, EffectResult::Resolved);
    // Hand size unchanged; no damage dealt; no powers spawned.
    assert_eq!(state.player.hand.len(), hand_len);
    assert_eq!(state.creatures[0].current_hp, 100);
    assert!(state.powers.is_empty());
}

