/// Anointed (bead `sts2-rs-h2nh`): every RARE-rarity card in the
/// draw pile is moved to hand; non-RARE cards stay put. The
/// rarity lookup is performed by `card_rarity_for_id` over the
/// generated spec slices.
#[test]
fn play_anointed_pulls_rare_draw_cards_into_hand() {
    install_pool();
    let (mut state, _) = fresh_state(CardId::Anointed, 0, 0);
    // Seed draw with one RARE (Apotheosis -> RARE in spec), one
    // Common (Strike), and one Uncommon (Anger). Use stable
    // factories so the test is rebaseable when specs change.
    let rare_spec = crate::cards::ironclad::barricade::spec();
    assert_eq!(rare_spec.rarity, super::super::types::CardRarity::Rare);
    let common_spec = crate::cards::ironclad::strike_ironclad::spec();
    assert_ne!(
        common_spec.rarity,
        super::super::types::CardRarity::Rare,
        "Strike must not itself be RARE — would defeat the test"
    );
    for spec in [&rare_spec, &common_spec] {
        let raw = u32::try_from(state.cards.len() + 1).expect("fits");
        let uid = CardUid::new(raw).expect("nz");
        let mut card = card_from_spec(spec);
        card.uid = uid;
        state.cards.push(card);
        state.player.draw.push(uid);
    }
    let rare_uid = state.player.draw[0];
    let common_uid = state.player.draw[1];
    let f = lookup(CardId::Anointed).expect("registered");
    let _ = f(&mut state, None);
    assert!(
        state.player.hand.contains(&rare_uid),
        "rare card must land in hand"
    );
    assert!(
        !state.player.hand.contains(&common_uid),
        "starter card must stay in draw"
    );
    assert!(
        state.player.draw.contains(&common_uid),
        "starter card retained in draw"
    );
    assert!(
        !state.player.draw.contains(&rare_uid),
        "rare card removed from draw"
    );
}

/// `card_rarity_for_id` MUST resolve Rare-rarity cards for EVERY character
/// pool — including Regent and Necrobinder, whose spec slices were omitted from
/// the scan, so Anointed's `c.Rarity == Rare` filter found nothing and pulled
/// no cards on those characters (parity PILE_COUNT|ANOINTED). Bead
/// `sts2-rs-6ynt.8` follow-up.
#[test]
fn card_rarity_resolves_regent_and_necrobinder_rares() {
    use super::helpers::card_rarity_for_id;
    use crate::cards::types::CardRarity;
    // Regent Rare (Anointed pulled BOMBARDMENT/BUNDLE_OF_JOY/HEAVENLY_DRILL in
    // C#; Rust resolved None for all three -> empty pool).
    assert_eq!(
        card_rarity_for_id(CardId::Bombardment),
        Some(CardRarity::Rare),
        "Regent BOMBARDMENT must resolve as Rare"
    );
    assert_eq!(
        card_rarity_for_id(CardId::HeavenlyDrill),
        Some(CardRarity::Rare),
        "Regent HEAVENLY_DRILL must resolve as Rare"
    );
    // Necrobinder Rare.
    assert_eq!(
        card_rarity_for_id(CardId::BansheesCry),
        Some(CardRarity::Rare),
        "Necrobinder BANSHEES_CRY must resolve as Rare"
    );
}

/// v0.107.1 Anointed caps the rares moved by FREE hand space
/// (`MaxCardsInHand - Hand.Count`). With 2 rares in draw but only 1 free hand
/// slot, exactly ONE rare moves; the other stays in the draw pile. (The picked
/// subset is RNG-selected, so we assert counts, not identity.)
#[test]
fn play_anointed_caps_rares_by_free_hand_space() {
    use sts2_core::CardUid;
    install_pool();
    let (mut state, _) = fresh_state(CardId::Anointed, 0, 0);
    // Fill the hand to leave exactly ONE free slot (HAND_LIMIT - 1).
    let target_hand = sts2_core::cards::HAND_LIMIT - 1;
    let filler = crate::cards::ironclad::strike_ironclad::spec();
    while state.player.hand.len() < target_hand {
        let raw = u32::try_from(state.cards.len() + 1).expect("fits");
        let uid = CardUid::new(raw).expect("nz");
        let mut card = card_from_spec(&filler);
        card.uid = uid;
        state.cards.push(card);
        state.player.hand.push(uid);
    }
    // Two RARE cards in the draw pile.
    let rare_spec = crate::cards::ironclad::barricade::spec();
    assert_eq!(rare_spec.rarity, super::super::types::CardRarity::Rare);
    let mut rares = Vec::new();
    for _ in 0..2 {
        let raw = u32::try_from(state.cards.len() + 1).expect("fits");
        let uid = CardUid::new(raw).expect("nz");
        let mut card = card_from_spec(&rare_spec);
        card.uid = uid;
        state.cards.push(card);
        state.player.draw.push(uid);
        rares.push(uid);
    }
    let f = lookup(CardId::Anointed).expect("registered");
    let _ = f(&mut state, None);
    assert_eq!(
        state.player.hand.len(),
        sts2_core::cards::HAND_LIMIT,
        "hand filled to cap — exactly one rare moved into the free slot"
    );
    let rares_in_hand = rares
        .iter()
        .filter(|u| state.player.hand.contains(u))
        .count();
    let rares_in_draw = rares
        .iter()
        .filter(|u| state.player.draw.contains(u))
        .count();
    assert_eq!(rares_in_hand, 1, "only one rare moved (free space = 1)");
    assert_eq!(rares_in_draw, 1, "the other rare stayed in the draw pile");
}

/// A FULL hand still shuffles the rares: C# `TakeRandom(0, rng)` runs the
/// whole `UnstableShuffle` (`IEnumerableExtensions.cs:19`,
/// `ListExtensions.cs:45`) before `Take(0)`, so 3 rares cost 2
/// `CombatCardSelection` reads even though nothing moves. Silent full-tier
/// seed:5474 (History Course replaying Anointed into a retained 10-card hand).
#[test]
fn play_anointed_full_hand_still_consumes_card_selection_rng() {
    use sts2_core::CardUid;
    install_pool();
    let (mut state, _) = fresh_state(CardId::Anointed, 0, 0);
    let filler = crate::cards::ironclad::strike_ironclad::spec();
    while state.player.hand.len() < sts2_core::cards::HAND_LIMIT {
        let raw = u32::try_from(state.cards.len() + 1).expect("fits");
        let uid = CardUid::new(raw).expect("nz");
        let mut card = card_from_spec(&filler);
        card.uid = uid;
        state.cards.push(card);
        state.player.hand.push(uid);
    }
    let rare_spec = crate::cards::ironclad::barricade::spec();
    let rares: Vec<CardUid> = (0..3)
        .map(|_| push_draw_card(&mut state, &rare_spec))
        .collect();
    let before = state.run_rng.combat_card_selection.counter();
    let f = lookup(CardId::Anointed).expect("registered");
    let _ = f(&mut state, None);
    assert_eq!(
        state.run_rng.combat_card_selection.counter() - before,
        2,
        "UnstableShuffle of 3 rares reads n-1 = 2 times even with 0 free slots"
    );
    assert!(
        rares.iter().all(|u| state.player.draw.contains(u)),
        "nothing moved"
    );
}

/// GangUp (bead `sts2-rs-q6bix`, F-R follow-up): C# `GangUp` deals
/// `CalculatedDamage = Base(5) + Extra(5) × allyPoweredHits`, where the
/// multiplier counts OTHER same-side allies' powered attacks this turn
/// (`e.Dealer != Owner.Creature && e.Dealer.Side == Owner.Side`). In a
/// solo Ironclad arena there are no allies, so the multiplier is always 0
/// and the card deals a flat 5 — NOT the player's own `powered_hits`.
#[test]
fn gang_up_deals_flat_base_in_solo_ignoring_player_own_hits() {
    install_pool();
    let (mut state, euid) = fresh_state(CardId::GangUp, 0, 0);
    // The player has landed 3 powered hits this turn. The OLD buggy
    // handler multiplied by this; C# excludes self, so it must be ignored.
    state.player.powered_hits_this_turn = 3;
    let f = lookup(CardId::GangUp).expect("registered");
    let _ = f(&mut state, Some(euid));
    assert_eq!(
        state.creatures[0].current_hp, 95,
        "GangUp deals flat base 5 in solo (no allies), not player's own powered hits"
    );
}

/// Helper: push a fresh card built from `spec` onto the draw pile,
/// returning its uid.
fn push_draw_card(state: &mut CombatState, spec: &super::super::types::CardSpec) -> CardUid {
    let raw = u32::try_from(state.cards.len() + 1).expect("fits");
    let uid = CardUid::new(raw).expect("nz");
    let mut card = card_from_spec(spec);
    card.uid = uid;
    state.cards.push(card);
    state.player.draw.push(uid);
    uid
}

