/// Helper: push `n` sentinel Strikes into hand, returning their uids.
fn push_hand_strikes(state: &mut CombatState, n: usize) -> Vec<CardUid> {
    let mut uids = Vec::new();
    for _ in 0..n {
        let raw = u32::try_from(state.cards.len() + 1).expect("fits");
        let uid = CardUid::new(raw).expect("nz");
        let mut card = card_from_spec(&crate::cards::ironclad::strike_ironclad::spec());
        card.uid = uid;
        state.cards.push(card);
        state.player.hand.push(uid);
        uids.push(uid);
    }
    uids
}

/// Purity (bead `sts2-rs-1xmxp`): opens an `ExhaustFromHand` player
/// choice (min 0, max = `PURITY_MAX_EXHAUST` clamped to hand size,
/// skippable) instead of a random exhaust. With a 2-card hand the
/// choice offers both; resolving exhausts the chosen ones.
#[test]
fn play_purity_opens_exhaust_choice_then_resolves() {
    install_pool();
    let (mut state, _) = fresh_state(CardId::Purity, 0, 0);
    let strikes = push_hand_strikes(&mut state, 2);
    let f = lookup(CardId::Purity).expect("registered");
    assert_eq!(f(&mut state, None), EffectResult::Resolved);
    let pc = state
        .pending_choice
        .as_ref()
        .expect("exhaust choice opened");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::ExhaustFromHand);
    assert_eq!(pc.min_select, 0);
    assert_eq!(pc.max_select, 2, "max clamped to the 2-card hand");
    assert!(pc.can_skip);
    assert!(state.player.exhaust.is_empty(), "no exhaust until resolved");

    let selection: smallvec::SmallVec<[u8; 4]> = [0u8, 1].into_iter().collect();
    let res = sts2_core::apply(&mut state, sts2_core::Action::ResolveChoice { selection });
    assert_eq!(res, sts2_core::StepResult::Advanced);
    assert!(state.pending_choice.is_none());
    assert!(state.player.exhaust.contains(&strikes[0]));
    assert!(state.player.exhaust.contains(&strikes[1]));
    assert!(!state.player.hand.contains(&strikes[0]));
    assert!(!state.player.hand.contains(&strikes[1]));
}

/// Purity with a 5-card hand caps the selection at `PURITY_MAX_EXHAUST`
/// (=3): the choice offers all 5 but `max_select` is 3, and resolving
/// the first 3 leaves 2 in hand.
#[test]
fn play_purity_caps_selection_at_three_when_hand_is_larger() {
    install_pool();
    let (mut state, _) = fresh_state(CardId::Purity, 0, 0);
    let strikes = push_hand_strikes(&mut state, 5);
    let f = lookup(CardId::Purity).expect("registered");
    assert_eq!(f(&mut state, None), EffectResult::Resolved);
    let pc = state
        .pending_choice
        .as_ref()
        .expect("exhaust choice opened");
    assert_eq!(pc.options.len(), 5, "all 5 hand cards offered");
    assert_eq!(
        u32::from(pc.max_select),
        super::PURITY_MAX_EXHAUST as u32,
        "selection capped at PURITY_MAX_EXHAUST (=3)",
    );

    let selection: smallvec::SmallVec<[u8; 4]> = [0u8, 1, 2].into_iter().collect();
    let res = sts2_core::apply(&mut state, sts2_core::Action::ResolveChoice { selection });
    assert_eq!(res, sts2_core::StepResult::Advanced);
    for s in &strikes[0..3] {
        assert!(state.player.exhaust.contains(s), "first 3 exhausted");
    }
    assert!(state.player.hand.contains(&strikes[3]));
    assert!(state.player.hand.contains(&strikes[4]));
}

