/// Bead `sts2-rs-rnyme`: GoldAxe damage equals
/// `TurnEvents::player_card_plays_this_combat` (combat-wide FINISHED-play
/// counter), not the per-turn count. Pre-seed the counter to 4 finished
/// plays and play GoldAxe; assert the target took exactly 4 damage.
#[test]
fn rnyme_gold_axe_scales_with_player_card_plays_this_combat() {
    install_pool();
    let (mut state, target_uid) = fresh_state(CardId::GoldAxe, 0, 0);
    let hp_before = state
        .creatures
        .iter()
        .find(|c| c.id == target_uid.0)
        .map(|c| c.current_hp)
        .expect("target alive");

    // Pre-seed the combat-wide play counter to 4 FINISHED plays. The counter
    // is now bumped at play-FINISH (AFTER the effect dispatch), mirroring C#
    // `History.CardPlayFinished`, so it EXCLUDES the in-flight GoldAxe — the
    // handler reads it directly (no `- 1`). 4 finished plays → 4 damage.
    state.combat_log.player_card_plays_this_combat = 4;

    let f = lookup(CardId::GoldAxe).expect("registered");
    assert_eq!(f(&mut state, Some(target_uid)), EffectResult::Resolved);

    let hp_after = state
        .creatures
        .iter()
        .find(|c| c.id == target_uid.0)
        .map(|c| c.current_hp)
        .expect("target alive");

    assert_eq!(
        hp_before - hp_after,
        4,
        "GoldAxe deals the combat-wide FINISHED-play count (excludes its own in-flight play)",
    );
}

