/// Bead `sts2-rs-r9s6u`: Rend counts every (non-`ITemporaryPower`)
/// debuff on the target — including turn-decay debuffs like Weak
/// and Vulnerable, which the prior `duration != TurnEnd` filter
/// excluded. Apply Weak + Vulnerable + Poison to a 500-HP enemy
/// and play Rend: damage = 15 + 5 × 3 = 30 (before Vulnerable's
/// 1.5× multiplier on the attack itself → 45 to the target).
#[test]
fn r9s6u_rend_counts_weak_vulnerable_and_poison() {
    use sts2_core::card_effects::apply_power_to_enemy;
    install_pool();
    let (mut state, euid) = fresh_state(CardId::Rend, 0, 0);
    state.creatures[0].current_hp = 500;
    apply_power_to_enemy(&mut state, euid, PowerKind::Weak, 1);
    apply_power_to_enemy(&mut state, euid, PowerKind::Vulnerable, 1);
    apply_power_to_enemy(&mut state, euid, PowerKind::Poison, 2);

    let hp_before = state.creatures[0].current_hp;
    let f = lookup(CardId::Rend).expect("registered");
    let _ = f(&mut state, Some(euid));
    let raw = 15 + 5 * 3; // base + extra × (Weak + Vulnerable + Poison)
    let with_vuln = raw + raw / 2; // floor(raw × 1.5) from Vulnerable
    assert_eq!(
        hp_before - state.creatures[0].current_hp,
        with_vuln,
        "Rend: 15 + 5×3 = 30, ×1.5 (Vulnerable) → 45 damage"
    );
}

/// Rend must EXCLUDE `ITemporaryPower` debuffs, mirroring C#
/// `Rend.cs::ShouldCountPower` (`!(power is ITemporaryPower)`). A DarkShackles
/// application puts a `TemporaryStrengthPower` (`IsPositive => false`,
/// amount +15, reads as Debuff but IS an `ITemporaryPower`) on the enemy
/// alongside a real `Strength(-15)` debuff. C# counts ONLY the Strength
/// drain (1 debuff) → damage 15 + 5×1 = 20. The prior pure
/// `is_debuff_for_amount` filter wrongly counted both (2 → damage 25).
/// Surfaced by parity sweep seed 1428.
#[test]
fn rend_excludes_temporary_power_debuffs() {
    use sts2_core::card_effects::apply_power_to_enemy;
    install_pool();
    let (mut state, euid) = fresh_state(CardId::Rend, 0, 0);
    state.creatures[0].current_hp = 500;
    // DarkShackles: the temporary-strength marker (ITemporaryPower, +15)…
    apply_power_to_enemy(&mut state, euid, PowerKind::DarkShackles, 15);
    // …and the actual strength drain it represents (a real debuff at -15).
    // `apply_power_to_enemy` no-ops on amount <= 0, so seed +15 then flip the
    // sign to model the mid-combat drained-Strength state (cf. the
    // `f_d_positive_stack_removes_power_at_zero` fixture).
    apply_power_to_enemy(&mut state, euid, PowerKind::Strength, 15);
    let str_idx = state
        .powers
        .iter()
        .position(|p| p.kind == PowerKind::Strength)
        .expect("Strength applied");
    state.powers[str_idx].amount = -15;

    let hp_before = state.creatures[0].current_hp;
    let f = lookup(CardId::Rend).expect("registered");
    let _ = f(&mut state, Some(euid));
    // C# counts ONLY Strength(-15); DarkShackles is excluded (ITemporaryPower).
    let debuffs = 1; // only Strength(-15); DarkShackles excluded
    let expected = 15 + 5 * debuffs; // base + extra × 1 debuff = 20 (NOT 25)
    assert_eq!(
        hp_before - state.creatures[0].current_hp,
        expected,
        "Rend must exclude the ITemporaryPower DarkShackles: 15 + 5×1 = 20, not 25",
    );
}

