/// Bead `sts2-rs-5jgpx`: two Panache plays must create two SEPARATE
/// power instances (IsInstanced = true per C# `PanachePower.cs`), NOT
/// merge into one 24-damage stack.
///
/// C# ref: `PanachePower.cs` `IsInstanced => true`; `Panache.cs:24`
/// `DynamicVars["PanacheDamage"].BaseValue` (10 base, 14 upgraded).
#[test]
fn panache_is_instanced_two_plays_two_separate_powers() {
    install_pool();
    let (mut state, _euid) = fresh_state(CardId::PanacheCard, 0, 0);
    let player_id = NonZeroU32::new(99).expect("nz");
    state.creatures.push(Creature {
        id: player_id,
        current_hp: 80,
        max_hp: 80,
        block: 0,
        powers: SmallVec::new(),
        species: None,
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Player"),
        ai: None,
    });
    state.player.creature_uid = Some(CreatureUid(player_id));

    let f = lookup(CardId::PanacheCard).expect("registered");

    // Play base Panache (amount=10).
    f(&mut state, None);
    // Play upgraded Panache (amount=14).
    state.cards[0].upgraded = true;
    f(&mut state, None);

    // C# creates TWO separate instances (IsInstanced=true).
    let player_creature = state.creatures.iter().find(|c| c.id == player_id).unwrap();
    let panache_instances: Vec<i32> = player_creature
        .powers
        .iter()
        .filter_map(|puid| {
            state
                .powers
                .iter()
                .find(|p| p.id == puid.0 && p.kind == PowerKind::Panache)
                .map(|p| p.amount)
        })
        .collect();
    assert_eq!(
        panache_instances.len(),
        2,
        "two Panache plays → two separate instances (not merged); got {panache_instances:?}"
    );
    // The amounts must be 10 and 14 (not merged into 24).
    assert!(
        panache_instances.contains(&10),
        "base Panache amount=10 missing; got {panache_instances:?}"
    );
    assert!(
        panache_instances.contains(&14),
        "upgraded Panache amount=14 missing; got {panache_instances:?}"
    );
}

/// Bead `sts2-rs-5jgpx`: Panache counter initialized to -1 (alreadyApplied=false).
/// After the first `dispatch_after_card_played` call (for the Panache card
/// itself), the counter transitions to 5 (CardsLeft) without decrementing.
/// C# ref: `PanachePower.cs:47-52` `Data.alreadyApplied` skip on first call.
#[test]
fn panache_counter_init_and_first_card_skip() {
    use sts2_core::hooks::{dispatch_after_card_played, CardCtx};
    install_pool();
    let (mut state, _euid) = fresh_state(CardId::PanacheCard, 0, 0);
    let player_id = NonZeroU32::new(99).expect("nz");
    state.creatures.push(Creature {
        id: player_id,
        current_hp: 80,
        max_hp: 80,
        block: 0,
        powers: SmallVec::new(),
        species: None,
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Player"),
        ai: None,
    });
    state.player.creature_uid = Some(CreatureUid(player_id));

    let f = lookup(CardId::PanacheCard).expect("registered");
    f(&mut state, None); // apply base Panache (amount=10)

    // Immediately after play, counter should be -1.
    let player_creature = state.creatures.iter().find(|c| c.id == player_id).unwrap();
    let counter_before = player_creature
        .powers
        .iter()
        .find_map(|puid| {
            state
                .powers
                .iter()
                .find(|p| p.id == puid.0 && p.kind == PowerKind::Panache)
                .map(|p| p.counter)
        })
        .expect("Panache power present");
    assert_eq!(
        counter_before, -1,
        "fresh Panache starts at counter=-1 (alreadyApplied=false)"
    );

    // Fire dispatch_after_card_played for the Panache card itself.
    // C# skips the decrement on the first call (alreadyApplied=false → true).
    let ctx = CardCtx {
        card_id: Some(CardId::PanacheCard),
        ..CardCtx::default()
    };
    dispatch_after_card_played(&mut state, &ctx);

    let player_creature = state.creatures.iter().find(|c| c.id == player_id).unwrap();
    let counter_after = player_creature
        .powers
        .iter()
        .find_map(|puid| {
            state
                .powers
                .iter()
                .find(|p| p.id == puid.0 && p.kind == PowerKind::Panache)
                .map(|p| p.counter)
        })
        .expect("Panache power still present");
    assert_eq!(
        counter_after, 5,
        "after first AfterCardPlayed (Panache card itself), counter=5 (alreadyApplied=true, CardsLeft=5)"
    );
}

/// Bead `sts2-rs-5jgpx`: Panache deals `Amount` Unpowered damage to all enemies
/// after 5 cards are played post-application, then resets counter to 5.
/// C# ref: `PanachePower.cs:39-58`: decrement CardsLeft; at 0 `CreatureCmd.Damage(
/// context, CombatState.HittableEnemies, Amount, ValueProp.Unpowered, Owner)`.
#[test]
fn panache_triggers_damage_after_5_cards() {
    use sts2_core::hooks::{dispatch_after_card_played, CardCtx};
    install_pool();
    let (mut state, _euid) = fresh_state(CardId::PanacheCard, 0, 0);
    let player_id = NonZeroU32::new(99).expect("nz");
    state.creatures.push(Creature {
        id: player_id,
        current_hp: 80,
        max_hp: 80,
        block: 0,
        powers: SmallVec::new(),
        species: None,
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Player"),
        ai: None,
    });
    state.player.creature_uid = Some(CreatureUid(player_id));

    let f = lookup(CardId::PanacheCard).expect("registered");
    f(&mut state, None); // apply base Panache (amount=10)

    // First call: the Panache card itself → sets counter to 5.
    let panache_ctx = CardCtx {
        card_id: Some(CardId::PanacheCard),
        ..CardCtx::default()
    };
    dispatch_after_card_played(&mut state, &panache_ctx);

    // Subsequent 4 calls should decrement counter 5→4→3→2→1 without triggering.
    let enemy_hp_before = state.creatures[0].current_hp; // 100
    let generic_ctx = CardCtx::default();
    for expected_counter in [4, 3, 2, 1] {
        dispatch_after_card_played(&mut state, &generic_ctx);
        let player_creature = state.creatures.iter().find(|c| c.id == player_id).unwrap();
        let counter = player_creature
            .powers
            .iter()
            .find_map(|puid| {
                state
                    .powers
                    .iter()
                    .find(|p| p.id == puid.0 && p.kind == PowerKind::Panache)
                    .map(|p| p.counter)
            })
            .expect("Panache power present");
        assert_eq!(counter, expected_counter, "counter after decrement");
        assert_eq!(
            state.creatures[0].current_hp, enemy_hp_before,
            "no damage yet at counter={expected_counter}"
        );
    }

    // 5th card: counter reaches 0 → deal 10 damage to all enemies, reset to 5.
    dispatch_after_card_played(&mut state, &generic_ctx);
    assert_eq!(
        state.creatures[0].current_hp,
        enemy_hp_before - 10,
        "Panache (amount=10) deals 10 unpowered damage on trigger"
    );
    // Counter resets to 5.
    let player_creature = state.creatures.iter().find(|c| c.id == player_id).unwrap();
    let counter_after_trigger = player_creature
        .powers
        .iter()
        .find_map(|puid| {
            state
                .powers
                .iter()
                .find(|p| p.id == puid.0 && p.kind == PowerKind::Panache)
                .map(|p| p.counter)
        })
        .expect("Panache power still present after trigger");
    assert_eq!(
        counter_after_trigger, 5,
        "counter resets to 5 after trigger"
    );
}

/// Bead `sts2-rs-bm34f`: `DarkShacklesPower : TemporaryStrengthPower`
/// (IsPositive=false). C# `TemporaryStrengthPower.BeforeApplied`
/// (TemporaryStrengthPower.cs:123-133) fires `PowerCmd.Apply<Strength>`
/// only with the `ModifyPowerAmountReceived`-adjusted amount — which
/// `ArtifactPower.TryModifyPowerAmountReceived` (ArtifactPower.cs:16-34)
/// zeros for any visible debuff. The old Rust handler applied Strength
/// unconditionally before the DarkShackles apply, so Artifact-blocked plays
/// left a stale Strength(-9) with no DarkShackles to revert it.
///
/// With target Artifact(1): Artifact is consumed, DarkShackles is blocked →
/// only Artifact remains (powers.len == 0 after Artifact is consumed to 0
/// and removed; or powers.len == 1 if initial Artifact was 2 and one stack
/// remains). Crucially, Strength(-9) must NOT appear.
#[test]
fn dark_shackles_blocked_by_artifact_does_not_apply_strength() {
    install_pool();

    // Build a state with a target that has Artifact(2) — mirrors Chomper.
    let (mut state, euid) = fresh_state(CardId::DarkShackles, 0, 0);
    // Add Artifact(2) to the enemy creature's powers.
    let art_id = std::num::NonZeroU32::new(100).expect("nz");
    state.powers.push(sts2_core::Power {
        id: art_id,
        kind: PowerKind::Artifact,
        amount: 2,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.creatures[0].powers.push(sts2_core::PowerUid(art_id));

    let f = lookup(CardId::DarkShackles).expect("registered");
    f(&mut state, Some(euid));

    // Artifact(2) consumed 1 stack → Artifact(1) remains; DarkShackles
    // was blocked → no DarkShackles power on the creature; Strength must
    // NOT have been applied (the pre-fix bug left Strength(-9) here).
    let creature = &state.creatures[0];
    let has_dark_shackles = creature.powers.iter().any(|pu| {
        state
            .powers
            .iter()
            .any(|p| p.id == pu.0 && p.kind == PowerKind::DarkShackles)
    });
    let has_strength = creature.powers.iter().any(|pu| {
        state
            .powers
            .iter()
            .any(|p| p.id == pu.0 && p.kind == PowerKind::Strength)
    });
    let artifact_amount = creature.powers.iter().find_map(|pu| {
        state
            .powers
            .iter()
            .find(|p| p.id == pu.0 && p.kind == PowerKind::Artifact)
            .map(|p| p.amount)
    });

    assert!(
        !has_dark_shackles,
        "DarkShackles should be blocked by Artifact — not applied"
    );
    assert!(
        !has_strength,
        "Strength(-9) must NOT be applied when DarkShackles is blocked by Artifact \
         (C# BeforeApplied receives amount=0 → Strength(0) is a no-op)"
    );
    assert_eq!(
        artifact_amount,
        Some(1),
        "Artifact should have consumed one stack (2→1)"
    );
}

/// Bead `sts2-rs-bm34f`: Verify that DarkShackles on a target WITHOUT Artifact
/// still applies both DarkShackles(9) AND Strength(-9) as before.
#[test]
fn dark_shackles_no_artifact_still_applies_strength() {
    install_pool();
    let (mut state, euid) = fresh_state(CardId::DarkShackles, 0, 0);

    let f = lookup(CardId::DarkShackles).expect("registered");
    f(&mut state, Some(euid));

    let creature = &state.creatures[0];
    let dark_shackles_amount = creature.powers.iter().find_map(|pu| {
        state
            .powers
            .iter()
            .find(|p| p.id == pu.0 && p.kind == PowerKind::DarkShackles)
            .map(|p| p.amount)
    });
    let strength_amount = creature.powers.iter().find_map(|pu| {
        state
            .powers
            .iter()
            .find(|p| p.id == pu.0 && p.kind == PowerKind::Strength)
            .map(|p| p.amount)
    });

    assert_eq!(
        dark_shackles_amount,
        Some(9),
        "DarkShackles(9) should be applied when no Artifact is present"
    );
    assert_eq!(
        strength_amount,
        Some(-9),
        "Strength(-9) should be applied alongside DarkShackles when no Artifact blocks it"
    );
}

// ---------------------------------------------------------------------------
// Auto-play inline choice resolution (sts2-rs-y1fic).
// ---------------------------------------------------------------------------

/// Push a fresh Skill card into the **hand** pile. Returns its uid.
fn push_hand_card_id(state: &mut CombatState, card_id: CardId) -> CardUid {
    let raw = u32::try_from(state.cards.len() + 1).expect("fits");
    let uid = sts2_core::CardUid(NonZeroU32::new(raw).expect("nz"));
    state.cards.push(Card {
        uid,
        card_id,
        cost: sts2_core::CardEnergyCost::new(1),
        card_type: CardType::Skill,
        target_type: TargetType::Self_,
        upgraded: false,
        base_damage: 0,
        base_block: 0,
        ..Card::pod_defaults()
    });
    state.player.hand.push(uid);
    uid
}

/// Parity bug `combat_select_ironclad` (supersedes the prior y1fic
/// inline-drain expectation): the FIRST surfacing card-select an auto-played
/// card opens must SURFACE, not drain inline. C#'s headless `ICardSelector`
/// auto-resolves inline only for `count==0` or `count==1 && min>=1`.
/// Purity's `ExhaustFromHand` over 2 hand cards (count==2) is NOT one of those,
/// so the auto-played Purity leaves a `pending_choice` and the engine surfaces
/// a `card_select`. Resolving that choice (the harness/MCTS first-legal pick,
/// option index 0) then applies the exhaust and finishes the auto-play tail.
#[test]
fn auto_played_purity_surfaces_exhaust_choice() {
    install_pool();
    let (mut state, _euid) = fresh_state(CardId::Finesse, 0, 0);
    add_player_creature(&mut state);
    // Purity sits on top of the draw pile; two ordinary cards are in hand.
    let purity = push_draw_card_id(&mut state, CardId::Purity);
    let h0 = push_hand_card_id(&mut state, CardId::Finesse);
    let h1 = push_hand_card_id(&mut state, CardId::Finesse);
    let hand_before = state.player.hand.len();

    let played = sts2_core::combat_loop::auto_play_specific_card(&mut state, purity, false);
    assert!(played, "Purity auto-played off the draw pile");

    // The exhaust choice SURFACES: pending_choice is set, the auto-play is
    // suspended, and NOTHING has been exhausted yet.
    assert!(
        state.pending_choice.is_some(),
        "auto-played Purity must SURFACE its exhaust choice"
    );
    assert!(
        state.pending_autoplay_resume.is_some(),
        "the suspended auto-play is parked on pending_autoplay_resume"
    );
    assert_eq!(
        state.player.hand.len(),
        hand_before,
        "no hand card is exhausted until the surfaced choice resolves"
    );

    // Resolve the surfaced choice the way an MCTS agent would under the
    // SEQUENTIAL multi-pick decomposition (bead `sts2-rs-sopgf`): Purity's
    // exhaust is `min0/max3`, so a single `[0]` pick now ACCUMULATES and
    // re-opens (no effect fires); a following FINALIZE `[]` runs the resolver
    // over the accumulated `[0]` and finishes the suspended auto-play.
    let pick0: smallvec::SmallVec<[u8; 4]> = [0u8].into_iter().collect();
    let r = sts2_core::apply(
        &mut state,
        sts2_core::Action::ResolveChoice { selection: pick0 },
    );
    assert_eq!(
        r,
        sts2_core::StepResult::Advanced,
        "incremental pick re-opens"
    );
    assert!(
        state.pending_choice.is_some(),
        "the multi-pick re-opens after one incremental pick (no exhaust yet)"
    );
    assert_eq!(
        state.player.hand.len(),
        hand_before,
        "incremental pick fires NO exhaust"
    );
    let finalize: smallvec::SmallVec<[u8; 4]> = smallvec::SmallVec::new();
    let _ = sts2_core::apply(
        &mut state,
        sts2_core::Action::ResolveChoice {
            selection: finalize,
        },
    );

    assert!(
        state.pending_choice.is_none(),
        "the choice is resolved after FINALIZE"
    );
    assert!(
        state.pending_autoplay_resume.is_none(),
        "the suspended auto-play resumed and finished"
    );
    assert_eq!(
        state.player.hand.len(),
        hand_before - 1,
        "exactly one hand card exhausted by the resumed auto-play"
    );
    assert!(
        state.player.exhaust.contains(&h0),
        "the first hand option (index 0) was exhausted"
    );
    assert!(
        state.player.hand.contains(&h1),
        "only the first option was taken; the rest remain in hand"
    );
}

/// Parity bug `combat_select_ironclad`: in a Cascade-style two-card auto-play
/// where the FIRST collected card opens a surfacing choice, the auto-play
/// SUSPENDS on that first choice (the second card is stashed as remaining).
/// Resolving the first choice finishes the first card's tail then plays the
/// second card, whose own choice surfaces too: C# awaits each `CardCmd.AutoPlay`
/// and `FromHand` prompts the player for each (GH #1131). Net: each Purity
/// exhausts one hand card.
#[test]
fn two_auto_played_purities_each_surface_their_choice() {
    install_pool();
    let (mut state, _euid) = fresh_state(CardId::Finesse, 0, 0);
    add_player_creature(&mut state);
    // Two Purity cards collected from the draw top, plus four ordinary hand
    // cards so each Purity has a non-empty hand to exhaust from.
    push_draw_card_id(&mut state, CardId::Purity);
    push_draw_card_id(&mut state, CardId::Purity);
    let hand_cards: Vec<CardUid> = (0..4)
        .map(|_| push_hand_card_id(&mut state, CardId::Finesse))
        .collect();
    let hand_before = state.player.hand.len();

    sts2_core::combat_loop::auto_play_n_from_draw_top(&mut state, 2, /*force_exhaust=*/ false);

    // The FIRST Purity's choice surfaces; the second card is parked.
    assert!(
        state.pending_choice.is_some(),
        "the first auto-played Purity surfaces its exhaust choice"
    );
    assert!(
        state.pending_autoplay_resume.is_some(),
        "the suspended auto-play (with the second Purity as remaining) is parked"
    );
    assert_eq!(
        state.player.hand.len(),
        hand_before,
        "no hand card exhausted before the surfaced choice resolves"
    );

    // Resolve the surfaced choice under the SEQUENTIAL decomposition (bead
    // `sts2-rs-sopgf`): the first Purity's `min0/max3` exhaust takes one
    // incremental `[0]` pick (re-opens, no effect) then FINALIZE `[]` (exhaust
    // 1, finish the first Purity). The resume then plays the second Purity,
    // whose choice surfaces the same way.
    for purity in ["first", "second"] {
        let pick0: smallvec::SmallVec<[u8; 4]> = [0u8].into_iter().collect();
        let _ = sts2_core::apply(
            &mut state,
            sts2_core::Action::ResolveChoice { selection: pick0 },
        );
        assert!(
            state.pending_choice.is_some(),
            "{purity} Purity's multi-pick re-opens after one incremental pick"
        );
        let finalize: smallvec::SmallVec<[u8; 4]> = smallvec::SmallVec::new();
        let _ = sts2_core::apply(
            &mut state,
            sts2_core::Action::ResolveChoice {
                selection: finalize,
            },
        );
        if purity == "first" {
            assert_eq!(state.player.hand.len(), hand_before - 1);
            assert!(
                state.pending_choice.is_some(),
                "the second Purity surfaces its own exhaust choice"
            );
        }
    }

    assert!(
        state.pending_choice.is_none(),
        "no choice may be left pending after the resume completes"
    );
    assert!(
        state.pending_autoplay_resume.is_none(),
        "the suspended two-card auto-play resumed and finished"
    );
    // Each Purity exhausts one hand card, so two total.
    assert_eq!(
        state.player.hand.len(),
        hand_before - 2,
        "both auto-played Purities exhausted one hand card each"
    );
    let exhausted_hand = hand_cards
        .iter()
        .filter(|uid| state.player.exhaust.contains(uid))
        .count();
    assert_eq!(
        exhausted_hand, 2,
        "two distinct ordinary hand cards were exhausted by the two Purities"
    );
}

// ---------------------------------------------------------------------------
// GH #367 — epoch-gated unlocks prune the generation pools.
//
// These tests mutate the PROCESS-level unlock registry. That is safe here only
// because this repo runs `cargo nextest run` (one process per test) — see the
// testing rule in `CLAUDE.md`. Under plain `cargo test` they would collide
// with every other pool test in the binary.
// ---------------------------------------------------------------------------

/// The measured defect. C# `RegentCardPool.FilterThroughEpochs` prunes
/// Regent5Epoch when it is unrevealed, and that epoch holds exactly one Attack
/// (SUPERMASSIVE) — so the Attack sub-pool is 29 with the epoch revealed and 28
/// without. `UnstableShuffle` reads `len - 1` ints, which is why the live
/// Regent A1 corpus showed `combat_card_generation` at mirror = world + 1 on
/// 37/37 CROSSBOW end-turn records.
#[test]
fn an_unrevealed_epoch_shrinks_the_regent_attack_pool_by_one() {
    use crate::unlocks::{clear_locked_cards, set_locked_epochs, Epoch};
    use sts2_core::cards::CardType;
    use sts2_core::potions::CharacterId;

    let attacks = |pool: &[crate::cards::types::CardSpec]| {
        pool.iter()
            .filter(|s| s.card_type == CardType::Attack)
            .count()
    };

    clear_locked_cards();
    let all = super::helpers::combat_generatable_pool(CharacterId::Regent);
    let attacks_unlocked = attacks(all);

    set_locked_epochs(&[Epoch::Regent5]);
    let gated = super::helpers::combat_generatable_pool(CharacterId::Regent);

    assert_eq!(
        all.len() - gated.len(),
        3,
        "the whole 3-card epoch leaves the pool"
    );
    assert_eq!(
        attacks_unlocked - attacks(gated),
        1,
        "exactly one of Regent5's three cards is an Attack (SUPERMASSIVE)"
    );
    assert!(
        !gated.iter().any(|s| s.id == CardId::Supermassive),
        "the gated Attack is gone from the pool"
    );
    assert!(
        gated.iter().any(|s| s.id == CardId::Orbit),
        "an unrelated Regent card survives"
    );
    clear_locked_cards();
}

/// Filtering must preserve the surviving cards' relative order. C# prunes with
/// `List.RemoveAll` over the `GenerateAllCards()` order, and the pool order
/// decides which card a given RNG draw lands on — a reordered pool of the same
/// size would desync just as badly as a resized one.
#[test]
fn epoch_filtering_preserves_pool_order() {
    use crate::unlocks::{clear_locked_cards, set_locked_epochs, Epoch};
    use sts2_core::potions::CharacterId;

    clear_locked_cards();
    let all: Vec<CardId> = super::helpers::combat_generatable_pool(CharacterId::Regent)
        .iter()
        .map(|s| s.id)
        .collect();
    set_locked_epochs(&[Epoch::Regent5]);
    let gated: Vec<CardId> = super::helpers::combat_generatable_pool(CharacterId::Regent)
        .iter()
        .map(|s| s.id)
        .collect();

    let expected: Vec<CardId> = all
        .iter()
        .copied()
        .filter(|id| !Epoch::Regent5.cards().contains(id))
        .collect();
    assert_eq!(
        gated, expected,
        "survivors keep their GenerateAllCards order"
    );
    clear_locked_cards();
}

/// The default must be bit-identical to the pre-#367 engine: nothing locked
/// means no filtering, so the oracle / training / MCTS paths are untouched.
#[test]
fn nothing_locked_leaves_every_pool_untouched() {
    use crate::cards::spec_index::specs_for_character;
    use crate::unlocks::{any_locked, clear_locked_cards, Epoch};
    use sts2_core::potions::CharacterId;

    clear_locked_cards();
    assert!(!any_locked());
    for c in [
        CharacterId::Ironclad,
        CharacterId::Silent,
        CharacterId::Defect,
        CharacterId::Regent,
        CharacterId::Necrobinder,
    ] {
        let specs = specs_for_character(c);
        assert!(
            !specs.is_empty(),
            "{c:?} keeps its full run-layer spec slice"
        );
    }
    // Every epoch-gated card is reachable when nothing is locked — the
    // property that makes the default `UnlockState.all`, without pinning a
    // pool-size constant that the ordinary combat filters also move.
    let regent = super::helpers::combat_generatable_pool(CharacterId::Regent);
    for e in [Epoch::Regent2, Epoch::Regent5, Epoch::Regent7] {
        for c in e.cards() {
            assert!(
                regent.iter().any(|s| s.id == c),
                "{c:?} must be generatable when its epoch is revealed"
            );
        }
    }
}

/// The run layer prunes too — C# runs `FilterThroughEpochs` inside
/// `GetUnlockedCards`, which is upstream of card rewards and shop stock, not
/// only of combat generation. This is the half of #367 whose blast radius
/// reaches deck composition.
#[test]
fn an_unrevealed_epoch_also_prunes_the_run_layer_spec_slice() {
    use crate::cards::spec_index::specs_for_character;
    use crate::unlocks::{clear_locked_cards, set_locked_epochs, Epoch};
    use sts2_core::potions::CharacterId;

    clear_locked_cards();
    let before = specs_for_character(CharacterId::Regent).len();
    set_locked_epochs(&[Epoch::Regent5, Epoch::Regent7]);
    let after: Vec<CardId> = specs_for_character(CharacterId::Regent)
        .iter()
        .map(|f| f().id)
        .collect();
    assert_eq!(before - after.len(), 6, "two whole epochs pruned");
    for e in [Epoch::Regent5, Epoch::Regent7] {
        for c in e.cards() {
            assert!(!after.contains(&c), "{c:?} must not reach a card reward");
        }
    }
    clear_locked_cards();
}

/// GH #368.3 was filed as an unexplained residual: Call of the Void
/// over-consumes the `combat_card_generation` cursor by **exactly +6, in every
/// one of 13 Necrobinder samples**. That constant is the signature of a
/// constant pool-size difference, and #367's epoch census says Necrobinder5
/// AND Necrobinder7 are both unrevealed on the live save — 2 x 3 = 6 cards.
///
/// `CallOfTheVoidPower.BeforeHandDraw` samples the UNTYPED character pool, so
/// it loses the whole 6, unlike Regent's CROSSBOW which reads the Attack
/// sub-pool and lost only Regent5's single Attack (+1). The same census
/// predicts Regent's untyped potion pools drift by 3, which the issue also
/// measured (Rust 79 vs 76).
///
/// Three independent magnitudes, one explanation. This test pins the pool
/// arithmetic behind it; the cursor itself is a live-arm measurement.
#[test]
fn the_epoch_census_predicts_the_measured_cursor_drifts() {
    use crate::unlocks::{clear_locked_cards, set_locked_epochs, Epoch};
    use sts2_core::cards::CardType;
    use sts2_core::potions::CharacterId;

    let size = |c: CharacterId| super::helpers::combat_generatable_pool(c).len();
    let attacks = |c: CharacterId| {
        super::helpers::combat_generatable_pool(c)
            .iter()
            .filter(|s| s.card_type == CardType::Attack)
            .count()
    };

    clear_locked_cards();
    let (necro_all, regent_all, regent_atk_all) = (
        size(CharacterId::Necrobinder),
        size(CharacterId::Regent),
        attacks(CharacterId::Regent),
    );

    // Necrobinder, untyped pool, two epochs locked -> the measured +6.
    set_locked_epochs(&[Epoch::Necrobinder5, Epoch::Necrobinder7]);
    assert_eq!(
        necro_all - size(CharacterId::Necrobinder),
        6,
        "Call of the Void's untyped pool loses both epochs in full"
    );

    // Regent, one epoch locked: +3 untyped (the potion pools) and +1 on the
    // Attack sub-pool (CROSSBOW's UnstableShuffle).
    set_locked_epochs(&[Epoch::Regent5]);
    assert_eq!(
        regent_all - size(CharacterId::Regent),
        3,
        "the untyped Regent pool loses all 3 of Regent5"
    );
    assert_eq!(
        regent_atk_all - attacks(CharacterId::Regent),
        1,
        "the Attack sub-pool loses only SUPERMASSIVE"
    );
    clear_locked_cards();
}

// ---------------------------------------------------------------------------
// GH #422 — "dispatch: empty Play pile"
// ---------------------------------------------------------------------------
//
// `current_damage` / `current_block` used to INFER the card being played from
// `state.player.play.last()` and `expect()` on it. That inference is only
// valid while the resolving card is still on the Play pile, and it need not
// be: C# `CardModel.OnPlayWrapper` runs every play iteration on `this` and
// guards its own disposal with `Pile?.Type == PileType.Play`
// (`CardModel.cs:1975`) precisely because an effect can move the card out
// mid-resolve.
//
// The port made that reachable. Repro (found by a randomized combat sweep,
// ~1 in 130k combats — matching the ~1-in-17k-runs rate in the issue):
//
//   1. StampedePower(2) auto-plays a random hand Attack at AutoPostPlay.
//      The first pick is SEEKER_STRIKE, whose `OnPlay` SURFACES a draw-pile
//      select — so its play tail parks on `pending_autoplay_resume`.
//   2. The Stampede batch does not await it: the loop auto-plays BOLAS too,
//      which lands on the Play pile behind SEEKER_STRIKE and parks its own
//      tail on the resume's `parent_chain`. Both cards are now stuck on the
//      Play pile while the end-turn chain runs on into the next turn's setup.
//   3. Resolving the surfaced select re-enters SEEKER_STRIKE's tail; a replay
//      of it opens a nested select, which drains inline and reaches the
//      deferred turn setup — whose BOLAS / THRUMMING_HATCHET return-to-hand
//      sweep scans EVERY non-Hand pile, Play included, and pulls BOLAS off it.
//   4. SEEKER_STRIKE's disposal then empties the Play pile, and BOLAS's parked
//      replay dispatches against it: `play.last()` is `None` → panic, run lost.
//
// The engine now STATES the resolving card (`CombatState::resolving_card`, set
// by `card_effects::dispatch_for_card`) instead of inferring it, so a replay
// reads its own base values wherever the card has ended up — which is what C#
// does. These pin that contract at the helper that used to panic.

/// Step 4 of the repro, isolated: the resolving card has been moved off the
/// Play pile (to Hand, as the turn-start return sweep does) and the pile is
/// now EMPTY. The dispatch must still deal BOLAS's own damage instead of
/// panicking with "dispatch: empty Play pile".
#[test]
fn gh422_replay_after_card_left_play_pile_reads_its_own_damage() {
    crate::cards::dispatch::ensure_installed();
    let (mut state, enemy) = fresh_state(CardId::Bolas, 3, 0);
    let uid = state.player.play[0];

    // The turn-start Bolas/ThrummingHatchet sweep moved it Play -> Hand while
    // its second play was still owed.
    state.player.play.clear();
    state.player.hand.push(uid);

    let hp_before = state.creatures[0].current_hp;
    let _ = sts2_core::card_effects::dispatch_for_card(&mut state, uid, CardId::Bolas, Some(enemy));

    assert_eq!(
        hp_before - state.creatures[0].current_hp,
        3,
        "a replay of a card that has left the Play pile still deals ITS OWN base damage"
    );
    assert!(
        state.resolving_card.is_none(),
        "dispatch_for_card must restore `resolving_card` on the way out"
    );
}

/// The sibling case: `auto_play_n_from_draw_top` pre-collects several cards
/// onto the Play pile, so `play.last()` can name a card that is NOT the one
/// being dispatched. The stated identity must win over the pile top.
#[test]
fn gh422_dispatch_reads_the_stated_card_not_the_play_pile_top() {
    crate::cards::dispatch::ensure_installed();
    let (mut state, enemy) = fresh_state(CardId::Bolas, 3, 0);
    let bolas = state.player.play[0];

    // A pre-collected sibling sits ON TOP of the resolving card.
    let sibling = sts2_core::CardUid(NonZeroU32::new(2).expect("nz"));
    state.cards.push(Card {
        uid: sibling,
        card_id: CardId::Clash,
        cost: sts2_core::CardEnergyCost::new(0),
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        upgraded: false,
        base_damage: 42,
        base_block: 0,
        ..Card::pod_defaults()
    });
    state.player.play.push(sibling);

    let hp_before = state.creatures[0].current_hp;
    let _ =
        sts2_core::card_effects::dispatch_for_card(&mut state, bolas, CardId::Bolas, Some(enemy));

    assert_eq!(
        hp_before - state.creatures[0].current_hp,
        3,
        "the dispatch must read BOLAS's 3, not the sibling's 42"
    );
}

/// Back-compat: a bare `dispatch` (no stated card — the shape every unit test
/// in this crate and the curse/status audit harness use) still falls back to
/// the historical `play.last()` inference.
#[test]
fn gh422_bare_dispatch_still_falls_back_to_the_play_pile_top() {
    crate::cards::dispatch::ensure_installed();
    let (mut state, enemy) = fresh_state(CardId::Bolas, 3, 0);
    let hp_before = state.creatures[0].current_hp;
    let _ = sts2_core::card_effects::dispatch(&mut state, CardId::Bolas, Some(enemy));
    assert_eq!(hp_before - state.creatures[0].current_hp, 3);
}

/// A nested auto-play (a card whose `OnPlay` auto-plays another) must restore
/// its CALLER as the resolving card when it returns — the outer card's own
/// remaining iterations still read the outer card.
#[test]
fn gh422_nested_dispatch_restores_the_outer_resolving_card() {
    crate::cards::dispatch::ensure_installed();
    let (mut state, enemy) = fresh_state(CardId::Bolas, 3, 0);
    let bolas = state.player.play[0];

    let outer = sts2_core::CardUid(NonZeroU32::new(9).expect("nz"));
    state.resolving_card = Some(outer);
    let _ =
        sts2_core::card_effects::dispatch_for_card(&mut state, bolas, CardId::Bolas, Some(enemy));
    assert_eq!(
        state.resolving_card,
        Some(outer),
        "the nested dispatch must hand the caller's card back"
    );
    state.resolving_card = None;
}

/// GH #663: how many `PlayCard` actions the engine offers for the one card in
/// hand, and whether they carry a target.
fn play_actions_for_hand_card(state: &sts2_core::CombatState) -> Vec<Option<u8>> {
    sts2_core::legal_actions(state)
        .iter()
        .filter_map(|a| match a {
            sts2_core::Action::PlayCard {
                hand_index: 0,
                target,
            } => Some(*target),
            _ => None,
        })
        .collect()
}

/// A MadScience built from its REGISTRY SPEC — the state a synthetic deck
/// leaves it in — sitting in hand with three enemies on the board.
fn state_with_spec_mad_science_in_hand() -> sts2_core::CombatState {
    use sts2_core::{CardUid, CombatPhase, CreatureUid};
    let mut state = sts2_core::CombatState {
        rng: sts2_core::dotnet_rng::Rng::new(0_i32),
        ..Default::default()
    };
    state.player.current_hp = 80;
    state.player.max_hp = 80;
    state.player.energy = 3;
    state.phase = CombatPhase::PlayerPlayPhase;
    for i in 1..=3u32 {
        let id = NonZeroU32::new(i).expect("nz");
        state.creatures.push(Creature {
            id,
            current_hp: 100,
            max_hp: 100,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::Nibbit),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: MonsterId("Nibbit"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid(id));
    }
    let card = crate::cards::spec_index::card_pod_from_id(CardId::MadScience, false)
        .expect("MadScience has a spec");
    let uid = CardUid(NonZeroU32::new(1).expect("nz"));
    state.cards.push(sts2_core::cards::Card { uid, ..card });
    state.player.hand.push(uid);
    state
}

/// GH #663: an UNCONFIGURED MadScience is untargeted. C# `MadScience.cs:82-92`
/// reads `TargetType` off `TinkerTimeType`, which the TinkerTime event alone
/// writes (`TinkerTime.cs:90,148,156`); a card that never went through the
/// event holds `default(CardType)` — and C#'s enum starts at `None`, not
/// `Attack` — so `None != Attack` gives `TargetType.Self` and ONE play.
/// The C#-oracle sweep saw three (one per enemy) against C#'s one.
#[test]
fn gh663_unconfigured_mad_science_offers_one_untargeted_play() {
    install_pool();
    let state = state_with_spec_mad_science_in_hand();
    assert_eq!(
        play_actions_for_hand_card(&state),
        vec![None],
        "an unconfigured MadScience is TargetType.Self in C#"
    );
}

/// ...and the half that separates a fix keyed on the VARIANT from one keyed on
/// "MadScience is special": configured Attack, it targets each enemy.
#[test]
fn gh663_attack_mad_science_offers_one_play_per_enemy() {
    install_pool();
    let mut state = state_with_spec_mad_science_in_hand();
    set_mad_science_variant(&mut state.cards[0], CardType::Attack, TinkerTimeRider::None);
    assert_eq!(
        play_actions_for_hand_card(&state),
        vec![Some(0), Some(1), Some(2)],
        "TinkerTimeType == Attack is the ONLY case C# targets"
    );
}

/// Skill and Power configure back to untargeted, the same branch the
/// unconfigured card takes but reached with the variant actually set.
#[test]
fn gh663_skill_and_power_mad_science_stay_untargeted() {
    install_pool();
    for mode in [CardType::Skill, CardType::Power] {
        let mut state = state_with_spec_mad_science_in_hand();
        set_mad_science_variant(&mut state.cards[0], mode, TinkerTimeRider::None);
        assert_eq!(
            play_actions_for_hand_card(&state),
            vec![None],
            "{mode:?} MadScience is TargetType.Self"
        );
    }
}

/// A riderless Glam MadScience (7 damage) in a state the engine plays from
/// the hand (`manual`) or auto-plays from the draw pile.
fn glam_mad_science_state(manual: bool) -> (CombatState, CreatureUid) {
    crate::cards::dispatch::ensure_installed();
    let (mut state, enemy) = fresh_state(CardId::MadScience, 7, 0);
    state.player.play.clear();
    state.phase = sts2_core::CombatPhase::PlayerPlayPhase;
    state.player.energy = 3;
    let card = &mut state.cards[0];
    card.set_enchantment(sts2_core::cards::EnchantmentId::Glam, 1);
    if manual {
        state.player.hand.push(card.uid);
    } else {
        state.player.draw.insert(0, card.uid);
    }
    (state, enemy)
}

/// Glam replays a MadScience once, and its "used" bit must not land in the
/// TinkerTime rider: both lived on `VarKey::Generic`, so the Glam bit
/// (`0b10`) turned the packed `(Attack, None)` into another rider after the
/// first play. Ported from the manoj fork (`841f558f3`).
#[test]
fn glam_mad_science_replays_once_without_changing_its_rider() {
    for manual in [true, false] {
        let (mut state, enemy) = glam_mad_science_state(manual);
        if manual {
            let _ = sts2_core::apply(
                &mut state,
                sts2_core::Action::PlayCard {
                    hand_index: 0,
                    target: Some(0),
                },
            );
        } else {
            assert!(sts2_core::combat_loop::auto_play_card_from_draw_top(
                &mut state, false
            ));
        }
        assert_eq!(
            enemy_hp(&state, enemy),
            100 - 14,
            "manual {manual}: two hits of 7"
        );
        assert_eq!(
            mad_science_variant_of(&state.cards[0]),
            (CardType::Attack, TinkerTimeRider::None),
            "manual {manual}: the rider is untouched"
        );
    }
}

/// PARITY95 Necrobinder: BigHat's ethereal draw reads the fight's
/// combat-generatable pool for every character (BigHat.cs:21-33 ->
/// CardFactory.GetDistinctForCombat). Necrobinder and Regent used to get
/// nothing. The C# pools carry 0 / 0 / 1 / 2 / 8 canonically Ethereal cards
/// (Ironclad / Silent / Defect / Regent / Necrobinder).
#[test]
fn big_hat_ethereal_sampler_covers_every_character() {
    use sts2_core::potions::CharacterId;
    for (character, want) in [
        (CharacterId::Ironclad, 0),
        (CharacterId::Silent, 0),
        (CharacterId::Defect, 1),
        (CharacterId::Regent, 2),
        (CharacterId::Necrobinder, 2),
    ] {
        let mut state = CombatState::default();
        let uids = create_character_ethereal_cards_into_arena(&mut state, character, 2);
        assert_eq!(uids.len(), want, "{character:?}: Big Hat card count");
        let pool = super::helpers::fight_pool(&state, character);
        for uid in uids {
            let card = sts2_core::card_by_uid(&state.cards, uid).expect("minted");
            let spec = pool.iter().find(|s| s.id == card.card_id);
            assert!(
                spec.is_some_and(super::super::types::CardSpec::is_ethereal),
                "{character:?}: {:?} not an Ethereal combat-generatable card",
                card.card_id
            );
        }
    }
}

